    public void validateSuccessfulLogin(ExtentTest logInfo) {
        try {
            gl.waitForElementAfterReload(getDriver(), isharesPageObjects3.LNIATA_CODE, PAGE_LOAD_TIMEOUT);

            if (gl.existElement(isharesPageObjects3.LNIATA_CODE_AS_LIST)) {
                String USER_LNIATA = isharesPageObjects3.LNIATA_CODE.getText();
                String LNIATA = USER_LNIATA.substring(USER_LNIATA.indexOf("F"), USER_LNIATA.indexOf("F") + 6);
                sharesLNIATA.put(getDriverID(), LNIATA);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            } else {
                mFailureDescription.put(getDriverID(), "Failed to log in");
                Assert.fail("Couldn't do successful login");
            }


        } catch (Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

    }

