    public void performMassTransferBasedOnOriginAndDestination(ExtentTest logInfo) {

        try {

//              6:MT0302/09APRPTY-LAX.360/09APRPTY-LAX#ALL

            gl.ignoreTRNS(logInfo);
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String oldFlightNo = pax.getOldFlightNumber();
            String newFlightNo = pax.getSegmentFlight(0);
            String originCity = pax.getSegmentOriginCity(0);
            String destinationCity = pax.getSegmentDestinationCity(0);

            String massTransferCmd = "6:MT" + oldFlightNo + "/" + date + originCity + "-" + destinationCity + "." +
                    newFlightNo + "/" + date + originCity + "-" + destinationCity + "|ALL";
            System.out.println("CMD: " + massTransferCmd);
            gl.logCommand(logInfo, massTransferCmd);
            gl.sendCmdValidateResponse(massTransferCmd, "MOVE FROM FLIGHT", "SHIP NOT ASSIGNED", "PREVIOUS MASS TRANSFER DID NOT COMPLETE", logInfo);

            if (isharesPageObjects3.SHARES_RESPONSE.getText().contains("PREVIOUS MASS TRANSFER DID NOT COMPLETE"))
            {
                String clearLNIATA= "6:MT|CLEAR";
                gl.logCommand(logInfo, clearLNIATA);
                gl.sendCmdValidateResponse(clearLNIATA, "ALL PROCESSED", logInfo);

                String massTransferCmd1 = "6:MT" + oldFlightNo + "/" + date + originCity + "-" + destinationCity + "." +
                        newFlightNo + "/" + date + originCity + "-" + destinationCity + "|ALL";
                System.out.println("CMD: " + massTransferCmd1);
                gl.logCommand(logInfo, massTransferCmd1);
                gl.sendCmdValidateResponse(massTransferCmd1, "MOVE FROM FLIGHT", "SHIP NOT ASSIGNED", "PREVIOUS MASS TRANSFER DID NOT COMPLETE", logInfo);

            }

            if (isharesPageObjects3.SHARES_RESPONSE.getText().contains("SHIP NOT ASSIGNED")) {

                isharesPageObjects3.COMMAND_INPUTAREA_ISHARES.sendKeys(Keys.CONTROL + "a" + Keys.BACK_SPACE);
                isharesPage2.openFlight(logInfo, pax.getOldFlightNumber(), date, pax.getSegmentOriginCity(0));
                isharesPage2.openFlight(logInfo, pax.getSegmentFlight(0), date, pax.getSegmentOriginCity(0));

                isharesPageObjects3.FORMSIZE_DROPDOWN.click();
                isharesPageObjects3.FORMSIZE_SELECT1.click();
                gl.waitForProfileLoad();

                gl.logCommand(logInfo, massTransferCmd);
                gl.sendCmdValidateResponse(massTransferCmd, "MOVE FROM FLIGHT  " + pax.getSegmentFlight(0) + " TO FLIGHT  " + pax.getOldFlightNumber(), logInfo);
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }



