    public void accessToSharesGDSSystem(ExtentTest logInfo, String entry) {
        try {

            String command ;
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String Invaliddate = gl.sharesFormatDateFromGUI(-3);
            String OriginCity = pax.getSegmentOriginCity(0);

            //LD360/23JUNPTY-M
            //LD473/Y04OCTLAXPTY-D
            //LD473/07NOVLAXPTY-E

            if (entry.equalsIgnoreCase("LD_M")) {
                command = "LD" + pax.getSegmentFlight(0) + "/" + date + OriginCity + "-M";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "SPECIAL MEALS", logInfo);

            } else if (entry.equalsIgnoreCase("LD_D")) {
                command = "LD" + pax.getSegmentFlight(0) + "/" + pax.getCOS() + date + OriginCity + pax.getSegmentDestinationCity(0) + "-D";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "END", logInfo);

            } else if (entry.equalsIgnoreCase("LD_E")) {
                command = "LD" + pax.getSegmentFlight(0) + "/" + date + OriginCity + pax.getSegmentDestinationCity(0) + "-E";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "DEST", logInfo);
            } else if (entry.equalsIgnoreCase("LD_A")) {
                //LD360/22AUG PTY-A
                command = "LD" + pax.getSegmentFlight(0) + "/" + date + " "+ OriginCity  + "-A";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "DEST", logInfo);

            } else if (entry.equalsIgnoreCase("LD_S")) {
                command = "LD" + pax.getSegmentFlight(0) + "/" + date + OriginCity + pax.getSegmentDestinationCity(0) + "-S";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "DEST", logInfo);

            } else if (entry.equalsIgnoreCase("LCN_D")) {
                //LCN435/05OCTMCO-D
                command = "LCN" + pax.getSegmentFlight(0) + "/" + date + OriginCity + pax.getSegmentDestinationCity(0) + "-D";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "DEST", "NO NAMES", logInfo);

            } else if (entry.equalsIgnoreCase("LX_D")) {
                //LX120/Y18JUNPTYMEX-D
                command = "LX" + pax.getSegmentFlight(0) + "/" + pax.getCOS() + date + OriginCity + pax.getSegmentDestinationCity(0) + "-D";
                gl.sendCmdValidateResponse(command, "CNCLD PNL", logInfo);

            } else if (entry.equalsIgnoreCase("LD_UA")) {
                //LD360/22AUG PTY-D*UA
                command = "LD" + pax.getSegmentFlight(0) + "/" + pax.getCOS() + date + " "+ OriginCity  + "-D*UA";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "PNL", logInfo);

            }  else if (entry.equalsIgnoreCase("LD_MCR")) {
                //LD360/22AUG PTY-Q*MCRC1
                command = "LD" + pax.getSegmentFlight(0) + "/" + pax.getCOS() + date + " "+ OriginCity  + "-Q*MCRC1";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "NO NAMES", logInfo);

            } else if (entry.equalsIgnoreCase("LD_UACRC")) {
                //LD360/22AUG PTY-Q*UACRC1
                command = "LD" + pax.getSegmentFlight(0) + "/" + pax.getCOS() + date + " "+ OriginCity  + "-Q*UACRC1";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "NO NAMES", logInfo);

            } else if (entry.equalsIgnoreCase("LD_D_Invalid_Date")) {
                //LD120/Y08JUNPTYMEX-D
                command = "LX" + pax.getSegmentFlight(0) + "/" + pax.getCOS() + Invaliddate + OriginCity + pax.getSegmentDestinationCity(0) + "-D";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "INVLD DATE", logInfo);

            } else if (entry.equalsIgnoreCase("LD_D_WithouDestination")) {
                command = "LD" + pax.getSegmentFlight(0) + "/" + pax.getCOS() + date + OriginCity + "-D";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "PNL", pax.getPnr(), logInfo);

            } else if (entry.equalsIgnoreCase("LD_PC")) {
                //LD302/27DECPTYLAX-PC
                command = "LD" + pax.getSegmentFlight(0) + "/" + pax.getCOS() + date + OriginCity + "-PC";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, OriginCity, logInfo);

            } else if (entry.equalsIgnoreCase("LD__D")) {
                command = "LD" + pax.getSegmentFlight(0) + "/" + date + OriginCity + "-D";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "END", logInfo);

            }else if (entry.equalsIgnoreCase("LD_PC1")) {
                //LD302/27DECPTYLAX-PC
                command = "LD" + pax.getSegmentFlight(0) + "/" + date + OriginCity + pax.getSegmentDestinationCity(0) + "-PC";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, pax.getSegmentDestinationCity(0), logInfo);
            }
            else if (entry.equalsIgnoreCase("ListDisplayTypes")) {
                String[] ListDisplayTypes = {"W","F","G","H","I","M","N","O","P","R","S","U","V","W","X","Y","Z"};

                for (String listDisplayType : ListDisplayTypes) {
                    command = "L" + listDisplayType + pax.getSegmentFlight(0) + "/" + date + OriginCity + "-D";
                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, "PNL", pax.getSegmentFlight(0), "NO NAMES", logInfo);
                }
            }
            else if (entry.equalsIgnoreCase("LD__Q")) {
                command = "LD" + pax.getSegmentFlight(0) + "/" + date + OriginCity + "-Q"+pax.getPOS()+"33";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "PLACED ON Q 33", logInfo);

            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


