            String EndDate = gl.sharesFormatDateFromGUIWithYear(25);
            String flight = pax.getSegmentFlight(0);
            String Origin = pax.getSegmentOriginCity(0);

            //     TCRC01/KN*243-899/1MAY24-15JUL24
            String enterKNCommands = "TCRC01/KN*" + flight + "-899/" + StartDate + "-" + EndDate;
            gl.logCommand(logInfo, enterKNCommands);
            gl.sendCmdValidateResponse(enterKNCommands, "ITEM NOT IN TBL", logInfo);

            //    TCRC01/KN*T3-25
            enterKNCommands = "TCRC01/KN*T3-25";
            gl.logCommand(logInfo, enterKNCommands);
            gl.sendCmdValidateResponse(enterKNCommands, "ITEM NOT IN TBL", logInfo);

            //    TCRC01/KN*TL
