    public void enterVMLCommands(ExtentTest logInfo, String Entry) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String StartDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String flight = pax.getSegmentFlight(0);
            String Origin = pax.getSegmentOriginCity(0);
            String COS = pax.getCOS();

            if (Entry.equalsIgnoreCase("AUL")) {
                //     VML360/5NOV1/PTYAUL15
                String command = "VML" + flight + "/" + StartDate + "1/" + Origin + "AUL15";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "FACTS-", "SAME VALUE ENTERED", logInfo);
            } else if (Entry.equalsIgnoreCase("CAP")) {
                //    VML360/5NOV8/PTYCAP140
                String command = "VML" + flight + "/" + StartDate + "8/" + Origin + "CAP140";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "FACTS-", "SAME VALUE ENTERED", logInfo);
            } else if (Entry.equalsIgnoreCase("HLD")) {
                //    VML360/5NOV4/PTYHLD1
                String command = "VML" + flight + "/" + StartDate + "4/" + Origin + "HLD1";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "FACTS-", "SAME VALUE ENTERED", logInfo);
            } else if (Entry.equalsIgnoreCase("OND")) {
                //   VIM360/03JUN*OND
                String command = "VIM" + flight + "/" + StartDate + "*OND";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "FACTS", "SAME VALUE ENTERED", logInfo);
            } else if (Entry.equalsIgnoreCase("ALLADJ5")) {
                //   VML360/03JUNY/.ALLADJ5
                String command = "VML" + flight + "/" + StartDate + COS + "/.ALLADJ5";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "-FACTS-", "SAME VALUE ENTERED", logInfo);
            }else if (Entry.equalsIgnoreCase("AUL0")) {
                //     VML360/5NOV1/PTYAUL0
                String command = "VML" + flight + "/" + StartDate + "Y/" + Origin + "AUL0";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "FACTS-", "SAME VALUE ENTERED", logInfo);

            }else if (Entry.equalsIgnoreCase("VML_255")) {
                //     VML360/22APRY/PTYODT255
                String command = "VML" + flight + "/" + StartDate + "Y/"  + "PTYODT255";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "FACTS-", flight, logInfo);
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


