    public void enterInvalidPassenger(ExtentTest logInfo) {

        try {
            //       	6:195/10OCTPTY-TEST/ONE
            //          B0
            gl.ignoreTRNS(logInfo);
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String Date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String flight = pax.getSegmentFlight(0);
            String Origin = pax.getSegmentOriginCity(0);
            String Destination = pax.getSegmentDestinationCity(0);

            for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {
                pax = mPassengers.get(getDriverID()).get(0);
                String enterInvalidPassenger = "6:" + flight + "/" + Date
                        + Destination + "-"
                        + pax.getfName() + "UIUO" + "/" + pax.getlName() + "UI" + "\n" + "B0";

                gl.logCommand(logInfo, enterInvalidPassenger);
                gl.sendCopiedCmdValidateResponse2i(logInfo, enterInvalidPassenger, "158FLT NOT OPEN PTY", "INVLD FLT NUMBER/DATE");
                logInfo.pass("I perform checkin for alternate flight with invalid passenger name");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                String Response = isharesPageObjects3.SHARES_RESPONSE.getText();
                isharesPageObjects3.FORMSIZE_DROPDOWN.click();
                isharesPageObjects3.FORMSIZE_SELECT1.click();

                if (Response.contains("FLT NOT OPEN PTY")) {
                    isharesPage2.openFlight(logInfo, flight, Date, Origin);
                    gl.sendCopiedCmdValidateResponse2i(logInfo, enterInvalidPassenger, "INVLD FLT NUMBER/DATE", "MULTIPLE ITEMS");
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    isharesPageObjects3.FORMSIZE_DROPDOWN.click();
                    isharesPageObjects3.FORMSIZE_SELECT1.click();
                }
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

