    public void AssignSeatAfterCheckin(ExtentTest logInfo, String AssignSeatType) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String flight = pax.getSegmentFlight(0);
            String Date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String Origin = pax.getSegmentOriginCity(0);
            String COS = pax.getCOS();

            String Seatcmd = "";
            boolean SeatAssigned = false;
            String[] SeatAlphabet = {"A", "F"};

            //            6:*302/18JANPTY.Y
            String command2 = "6:*" + flight + "/" + Date + Origin + "." + COS;
            gl.sendCmdValidateResponse(command2, Origin, "@-AVAIL  .-TAKEN", logInfo);
            gl.ignoreTRNS(logInfo);

            for (int j = 0; j < mPassengers.get(getDriverID()).size(); j++) {
                pax = mPassengers.get(getDriverID()).get(j);
                gl.ignoreTRNS(logInfo);

                for (String Alphabet : SeatAlphabet)
                {
                    for (int i = 5; i <= 35; i++) {
                        //6:409/10JULSFO-TEST/PERRY#@35A
                        if (AssignSeatType.equalsIgnoreCase("ReplaceSeatAfterCheckin")) {
                            if (pax.getPaxType().equalsIgnoreCase("INF")) {
                                Seatcmd = "6:" + flight + "/" + Date
                                        + Origin + "-" + pax.getAccompaniedPaxDetails().getfName() + "/" + pax.getAccompaniedPaxDetails().getlName()
                                        + "|@" + i + Alphabet;
                            } else {
                                Seatcmd = "6:" + flight + "/" + Date
                                        + Origin + "-" + pax.getfName() + "/" + pax.getlName()
                                        + "|@" + i + Alphabet;
                            }
                            gl.logCommand(logInfo, Seatcmd);
                            gl.sendCmdValidateResponse(Seatcmd, logInfo);
                            logInfo.pass("I assign seat");


                        } else if (AssignSeatType.equalsIgnoreCase("BlockSeatAndAssign")) {
                            // 6:CB809/21SEPPTY.Y#@35A
                            Seatcmd = "6:CB" + flight + "/" + Date
                                    + Origin + "." + COS
                                    + "|" + i + Alphabet;
                            gl.logCommand(logInfo, Seatcmd);
                            gl.sendCmdValidateResponse(Seatcmd, logInfo);
                            logInfo.pass("I block the seat");

                        } else if (AssignSeatType.equalsIgnoreCase("6_U_ChangeSeat")) {
                            // 6-U391/06NOVSJO-AGIPI/TIII#@8D
                            Seatcmd = "6:U" + flight + "/" + Date
                                    + Origin + "-" + pax.getfName()
                                    + "/" + pax.getlName() + "|@" + i + Alphabet;
                            gl.logCommand(logInfo, Seatcmd);
                            gl.sendCmdValidateResponse(Seatcmd, logInfo);
                        } else if (AssignSeatType.equalsIgnoreCase("ReEntryForSeat")) {
                            // 6:R#@03F
                            Seatcmd = "6:R|@" + i + Alphabet;
                            gl.logCommand(logInfo, Seatcmd);
                            gl.sendCmdValidateResponse(Seatcmd, logInfo);
                        } else if (AssignSeatType.equalsIgnoreCase("HeldSeatAndAssign"))
                        {
                            // 6:H461/10AUGSJO-PETER/HARRY#6F
                            Seatcmd = "6:H" + flight + "/" + Date
                                    + Origin + "-" + pax.getfName() + "/" + pax.getlName()
                                    + "|" + i + Alphabet;
                            gl.logCommand(logInfo, Seatcmd);
                            gl.sendCmdValidateResponse(Seatcmd, logInfo);

                            if (isharesPageObjects3.SHARES_RESPONSE.getText().contains("MULTIPLE ITEMS")) {

                                String response1 = isharesPageObjects3.SHARES_RESPONSE.getText();

                                //Capturing ID for the PNR
                                int index = response1.indexOf(mPassengers.get(getDriverID()).get(0).getPnr());
                                String indexVal = response1.substring((index - 27), (index - 24)).trim();

                                String MultiListCmd = "6:LH-" + indexVal; // Selected pax with ID
                                gl.logCommand(logInfo, MultiListCmd);
                                gl.sendCmdValidateResponse(MultiListCmd, logInfo);
                            }
                        }
                        else if (AssignSeatType.equalsIgnoreCase("UnBlockSeatAndAssign")) {
                            // 6:CB809/21SEPPTY.Y#@35A
                            Seatcmd = "6:CB" + flight + "/" + Date
                                    + Origin + "." + COS
                                    + "|@" + i + Alphabet;
                            gl.logCommand(logInfo, Seatcmd);
                            gl.sendCmdValidateResponse(Seatcmd, logInfo);
                            logInfo.pass("I Unblock the seat");
                        }


                        String Response = isharesPageObjects3.SHARES_RESPONSE.getText();
                        if (Response.contains("FLT NOT OPEN") || Response.contains("SHIP NOT ASSIGNED")) {
                            isharesPage2.openFlight(logInfo, flight, Date, Origin);
                            isharesPageObjects3.FORMSIZE_DROPDOWN.click();
                            isharesPageObjects3.FORMSIZE_SELECT1.click();
                            gl.sendCmdValidateResponse(Seatcmd, logInfo);
                            Response = isharesPageObjects3.SHARES_RESPONSE.getText();
                        }

                        if (Response.contains("MULTIPLE ITEMS")) {

                            String response1 = isharesPageObjects3.SHARES_RESPONSE.getText();

                            //Capturing ID for the PNR
                            int index = response1.indexOf(mPassengers.get(getDriverID()).get(0).getPnr());
                            String indexVal = response1.substring((index - 27), (index - 24)).trim();

                            String MultiListCmd = "6:LK-" + indexVal; // Selected pax with ID
                            gl.logCommand(logInfo, MultiListCmd);
                            gl.copyCmdToClipboardAndPaste(MultiListCmd, isharesPageObjects3.FORMSIZE_SELECT2_TEXTAREA);
                            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                            gl.waitForProfileLoad();
                            isharesPageObjects3.SEND_ISHARES.click();
                        }

                        if (Response.contains(i + Alphabet)) {
                            if (!Response.contains("UNASSIGNED")) {
                                pax.setSeatNumber(i + Alphabet);
                                SeatAssigned = true;
                                gl.logCommand(logInfo,"*" + pax.getPnr());
                                gl.sendCmdValidateResponse("*" + pax.getPnr(), pax.getSeatNumber(), logInfo);
                                logInfo.pass("I validated seat assigned successfully");
                                break;
                            }
                        }
                        if (Response.contains("002-OK-")) {
                            pax.setSeatNumber(i + Alphabet);
                            SeatAssigned = true;
                            break;
                        }
                    }
                    if (SeatAssigned) {
                        break;
                    }
                }
            }
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
        }
    }


    public void passengerSpaceProtection(ExtentTest logInfo, String ProtectedType) {

        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String originCity = pax.getSegmentOriginCity(0);
            String flight = pax.getSegmentFlight(0);
            String StartDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            //        6:P243/06FEBPTY-JEM/KIM
            //        6:LD243/06FEBPTY-PD

            gl.ignoreTRNS(logInfo);
            for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {

                if (ProtectedType.equalsIgnoreCase("Normal")) {

                    pax = mPassengers.get(getDriverID()).get(i);
                    String passengerSpaceProtectionCmd = "6:P" + flight + "/" + StartDate
                            + originCity + "-" + pax.getfName() + "/" + pax.getlName();
                    gl.logCommand(logInfo, passengerSpaceProtectionCmd);
                    gl.sendCmdValidateResponse(passengerSpaceProtectionCmd, "PASSENGERS SPACE PROTECTED", logInfo);

                } else if (ProtectedType.equalsIgnoreCase("NonRevenue")) {

                    pax = mPassengers.get(getDriverID()).get(i);
                    String passengerSpaceProtectionCmd = "6:P" + flight + "/" + StartDate
                            + originCity + "-" + pax.getfName() + "/" + pax.getlName();
                    gl.logCommand(logInfo, passengerSpaceProtectionCmd);
                    gl.sendCmdValidateResponse(passengerSpaceProtectionCmd, "UNABLE TO PROTECT - PAX NOT OVERSOLD", logInfo);
                }
                if(pax.getIsSameSurname())
                    break;
            }

            if (ProtectedType.equalsIgnoreCase("Normal")) {
                String verifyingCmd = "6:LD" + flight + "/" + StartDate + originCity + "-PD";
                gl.logCommand(logInfo, verifyingCmd);
                gl.sendCmdValidateResponse(verifyingCmd, pax.getfName(), "PROTECT POST DEP", logInfo);
            }


        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            org.junit.Assert.fail("This step failed.. so stopping...");
        }
    }

