    public void BundleLongSellWithInvalidPaxData(ExtentTest logInfo, String Entry) {

        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String originCity = pax.getSegmentOriginCity(0);
            String flight = pax.getSegmentFlight(0);
            String StartDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String destinationCity = pax.getSegmentDestinationCity(0);
            String COS = pax.getCOS();
            String Airline = pax.getAirline(0);
            int TotalPax = mPassengers.get(getDriverID()).size();

            if (Entry.equalsIgnoreCase("MarriedSegment")) {
                String ReturnoriginCity = pax.getSegmentOriginCity(1);
                String Returnflight = pax.getSegmentFlight(1);
                String ReturnStartDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(1));
                String ReturndestinationCity = pax.getSegmentDestinationCity(1);
                String ReturnCOS = pax.getCOS();
                String ReturnAirline = pax.getAirline(1);

                // 0CM360Y26OCTPTYLAXNN1#0CM362Y27OCTLAXPTYNNS
                String Command = "0" + Airline + flight + COS + StartDate + originCity + destinationCity + "NN" + TotalPax +
                        "|" + "0" + ReturnAirline + Returnflight + ReturnCOS + ReturnStartDate + ReturnoriginCity + ReturndestinationCity + "NNS";
                gl.logCommand(logInfo, Command);
                gl.sendCmdValidateResponse(Command, "UNABLE TO PROCESS", logInfo);
            } else {
                // 0CM382Y11JUNPTYSFONN2
                String Command = "0" + Airline + flight + COS + StartDate + originCity + destinationCity + "NN" + (TotalPax + 1);
                gl.logCommand(logInfo, Command);
                gl.sendCmdValidateResponse(Command, flight, logInfo);
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void enterTLCommandToRunLessDepartureTime(ExtentTest logInfo, String Entry) {

        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String originCity = pax.getSegmentOriginCity(0);
            String Airline = pax.getAirline(0);
            String Date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));

            String DepartFlightTime = pax.getSegmentDepartureTime(0);

            if (DepartFlightTime.length() == 4) {
                DepartFlightTime = "0" + pax.getSegmentDepartureTime(0);
            }
            String meridian1 = "";
            if (DepartFlightTime.contains("A")) {
                DepartFlightTime = DepartFlightTime.split("A")[0];
                meridian1 = "A";
            } else {
                DepartFlightTime = DepartFlightTime.split("P")[0];
                meridian1 = "P";
            }
            int departTime = Integer.parseInt(DepartFlightTime) + 20;
            String DepartTime = departTime + meridian1;

            if (Entry.equalsIgnoreCase("TLWithOrigin")) {
                // 8PTYCMTL600A
                String enterTLCommandToRunLessDepartureTime = "8" + originCity + Airline + "TL" + (departTime - 40) + meridian1;
                gl.logCommand(logInfo, enterTLCommandToRunLessDepartureTime);
                gl.sendCmdValidateResponse(enterTLCommandToRunLessDepartureTime, enterTLCommandToRunLessDepartureTime + " *", logInfo);
            } else if (Entry.equalsIgnoreCase("TL")) {
                // 8TL615P
                String enterTLCommandToRunLessDepartureTime = "8TL" + DepartTime;
                gl.logCommand(logInfo, enterTLCommandToRunLessDepartureTime);
                gl.sendCmdValidateResponse(enterTLCommandToRunLessDepartureTime, enterTLCommandToRunLessDepartureTime + " *", logInfo);
            } else if (Entry.equalsIgnoreCase("TLWithDate")) {
                // 8CMPTY747A/08JUN
                String enterTLCommandToRunLessDepartureTime = "8" + originCity + Airline + "1100A/" + Date;
                gl.logCommand(logInfo, enterTLCommandToRunLessDepartureTime);
                gl.sendCmdValidateResponse(enterTLCommandToRunLessDepartureTime, enterTLCommandToRunLessDepartureTime + " *", logInfo);
            }
            else if (Entry.equalsIgnoreCase("TLGreaterThanDepartTime")) {
                // 8TL615P
                String enterTLCommandToRunLessDepartureTime = "8TL" + DepartTime;
                gl.logCommand(logInfo, enterTLCommandToRunLessDepartureTime);
                gl.sendCmdValidateResponse(enterTLCommandToRunLessDepartureTime, enterTLCommandToRunLessDepartureTime + " *", logInfo);
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


