    public void cancelCheckin(ExtentTest logInfo) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));

            for (Passenger pax1 : mPassengers.get(getDriverID())) {

                String command ;

                if (pax1.getPaxType().equalsIgnoreCase("INF")) {
                    command = "6:" + pax.getSegmentFlight(0) + "/" + date + pax.getSegmentOriginCity(0) + "-"
                            + pax1.getAccompaniedPaxDetails().getfName() + "/" + pax1.getAccompaniedPaxDetails().getlName() + "|@";
                } else {
                    command = "6:" + pax.getSegmentFlight(0) + "/" + date + pax.getSegmentOriginCity(0) + "-"
                            + pax1.getfName() + "/" + pax1.getlName() + "|@";
                }

                //  6:474/06MARPTY-TEST/TOM#@

                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "SEATS UNASSIGNED", "MULTIPLE ITEMS", logInfo);

                if (isharesPageObjects3.SHARES_RESPONSE.getText().contains("MULTIPLE ITEMS"))
                {
                    String response = isharesPageObjects3.SHARES_RESPONSE.getText();

                    if(pax.getPnr()!=null)
                    {
                        //Capturing ID for the PNR
                        int index = response.indexOf(pax.getPnr());
                        String indexVal = response.substring((index - 27), (index - 24)).trim();

                        //6:LK-204#@
                        String MultiListCmd = "6:LK-" + indexVal + "|@";
                        gl.logCommand(logInfo, MultiListCmd);
                        gl.sendCmdValidateResponse(MultiListCmd, "SEATS UNASSIGNED", logInfo);
                    }

                    if(pax.getPnr2()!=null)
                    {
                        int index = response.indexOf(pax.getPnr2());
                        String indexVal = response.substring((index - 27), (index - 24)).trim();

                        //6:LK-204#@
                        String MultiListCmd = "6:LK-" + indexVal + "|@";
                        gl.logCommand(logInfo, MultiListCmd);
                        gl.sendCmdValidateResponse(MultiListCmd, "SEATS UNASSIGNED", logInfo);
                    }

                }

            }
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


    public void cancelCheckinMultiInitial(ExtentTest logInfo) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            boolean cancelled=false;
            String sameSurnamePax=pax.getfName();
            for(Passenger passenger: mPassengers.get(getDriverID()))
            {
                if (passenger.getIsSameSurname()) {
                    sameSurnamePax = sameSurnamePax + "/" + passenger.getlName();
                }
            }

            for (Passenger passenger : mPassengers.get(getDriverID())) {

                String command ;
                if(passenger.getIsSameSurname() && !cancelled)
                {
                    command = "6:" + pax.getSegmentFlight(0) + "/" + date + pax.getSegmentOriginCity(0) + "-"
                            + sameSurnamePax + "|@";
                    cancelled=true;

                    //  6:474/06MARPTY-TEST/TOM/HARRY#@
                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, "SEATS UNASSIGNED", "MULTIPLE ITEMS", logInfo);

                    if (isharesPageObjects3.SHARES_RESPONSE.getText().contains("MULTIPLE ITEMS"))
                    {
                        String response = isharesPageObjects3.SHARES_RESPONSE.getText();

                        if(pax.getPnr()!=null)
                        {
                            //Capturing ID for the PNR
                            int index = response.indexOf(pax.getPnr());
                            String indexVal = response.substring((index - 27), (index - 24)).trim();

                            //6:LK-204#@
                            String MultiListCmd = "6:LK-" + indexVal + "|@";
                            gl.logCommand(logInfo, MultiListCmd);
                            gl.sendCmdValidateResponse(MultiListCmd, "SEATS UNASSIGNED", logInfo);
                        }

                        if(pax.getPnr2()!=null)
                        {
                            int index = response.indexOf(pax.getPnr2());
                            String indexVal = response.substring((index - 27), (index - 24)).trim();

                            //6:LK-204#@
                            String MultiListCmd = "6:LK-" + indexVal + "|@";
                            gl.logCommand(logInfo, MultiListCmd);
                            gl.sendCmdValidateResponse(MultiListCmd, "SEATS UNASSIGNED", logInfo);
                        }

                    }
                }
                else if(!passenger.getIsSameSurname())
                {
                    if (passenger.getPaxType().equalsIgnoreCase("INF"))
                        command = "6:" + pax.getSegmentFlight(0) + "/" + date + pax.getSegmentOriginCity(0) + "-"
                                + passenger.getAccompaniedPaxDetails().getfName() + "/" + passenger.getAccompaniedPaxDetails().getlName() + "|@";
                    else
                        command = "6:" + pax.getSegmentFlight(0) + "/" + date + pax.getSegmentOriginCity(0) + "-"
                                + passenger.getfName() + "/" + passenger.getlName() + "|@";

                   //  6:474/06MARPTY-TEST/TOM#@
                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, "SEATS UNASSIGNED", "MULTIPLE ITEMS", logInfo);

                    if (isharesPageObjects3.SHARES_RESPONSE.getText().contains("MULTIPLE ITEMS"))
                    {
                        String response = isharesPageObjects3.SHARES_RESPONSE.getText();

                        if(pax.getPnr()!=null)
                        {
                            //Capturing ID for the PNR
                            int index = response.indexOf(pax.getPnr());
                            String indexVal = response.substring((index - 27), (index - 24)).trim();

                            //6:LK-204#@
                            String MultiListCmd = "6:LK-" + indexVal + "|@";
                            gl.logCommand(logInfo, MultiListCmd);
                            gl.sendCmdValidateResponse(MultiListCmd, "SEATS UNASSIGNED", logInfo);
                        }

                        if(pax.getPnr2()!=null)
                        {
                            gl.logCommand(logInfo, command);
                            gl.sendCmdValidateResponse(command, "SEATS UNASSIGNED", "MULTIPLE ITEMS", logInfo);

                            int index = response.indexOf(pax.getPnr2());
                            String indexVal = response.substring((index - 27), (index - 24)).trim();

                            //6:LK-204#@
                            String MultiListCmd = "6:LK-" + indexVal + "|@";
                            gl.logCommand(logInfo, MultiListCmd);
                            gl.sendCmdValidateResponse(MultiListCmd, "SEATS UNASSIGNED", logInfo);
                        }

                    }
                }
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

