    public void captureEquipmentNumberOfAFlight(ExtentTest logInfo, String segmentNo) {

        String fleetNo = null;
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);

            String Origin = pax.getSegmentOriginCity(Integer.parseInt(segmentNo) - 1);
            String Destination = pax.getSegmentDestinationCity(Integer.parseInt(segmentNo) - 1);
            int departureDate = pax.getSegmentDate(Integer.parseInt(segmentNo) - 1);
            int SegNo = Integer.parseInt(segmentNo) - 1;

            isharesPage2.displaySeatsAvailabilityForFlights(logInfo, Origin, Destination, SegNo, departureDate);//ExtentTest logInfo,String Origin, String Destination,int segmentNo,int departuredate
            String response = isharesPageObjects3.SHARES_RESPONSE.getText();
            for (int i = 1; i < response.split("\n").length; i++) {
                String row = response.split("\n")[i];
                if (row.contains("CM") || row.contains("UA")) {
                    int s = row.split(" ").length;

                    if (row.contains("*"))
                        fleetNo = row.split(" ")[s - 3];
                    else
                        fleetNo = row.split(" ")[s - 4];

                    String command = "6:ICICR-" + fleetNo + "-CCC";

                    isharesPageObjects3.COMMAND_INPUTAREA_ISHARES.click();
                    isharesPageObjects3.COMMAND_INPUTAREA_ISHARES.sendKeys(command);
                    isharesPageObjects3.SEND_ISHARES.click();
                    gl.waitForPageReload(getDriver(), isharesPageObjects3.SHARES_RESPONSE, PAGE_LOAD_TIMEOUT);
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    String resp = isharesPageObjects3.SHARES_RESPONSE.getText();
                    if (resp.contains("RESTRICTED ONLY FOR SEATING ENGINE"))
                        break;
                }
            }
            System.out.println("FleetNo :" + fleetNo);

            for (Passenger passenger : mPassengers.get(getDriverID()))
                passenger.setFleetNumber(fleetNo);

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

