    public void doubleAvailabilityOfFlightsSearch(ExtentTest logInfo, String Origin, String Destination1, String connectingCity1, String connectingCity2) {

        String command = null;
        try {

//            A 10DEC LAXNYC 800A 3DEN30/3ORD30/3

            Passenger pax = mPassengers.get(getDriverID()).get(0);

            String COS = mPassengers.get(getDriverID()).get(0).getCOS();
            int totalpax = mPassengers.get(getDriverID()).size();
            int departuredate = mPassengers.get(getDriverID()).get(0).getSegmentDate(0);  //Getting the departure Date based on feature file input

            int flag = 0;

            mPassengers.get(getDriverID()).get(0).setSegmentOriginCity(0, Origin);
            mPassengers.get(getDriverID()).get(0).setSegmentDestinationCity(0, Destination1);
            mPassengers.get(getDriverID()).get(0).setSegmentDate(0, departuredate);


            for (int i = departuredate; i <= departuredate + 5; i++) {  // loop for date

                String DateFormatted = gl.plusDaysFromTodayNew(i);
                LocalDateTime departdate = DateUtil.formatToLocalDateTime(DateFormatted, "10:10");
                String departureDateFormatted = DateUtil.formatDateToSharesDateFormat(departdate.toLocalDate());

                command = "A " + departureDateFormatted + Origin + Destination1 + " 800A 3" + connectingCity1 + "30/3" + connectingCity2 + "30/3";

                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, logInfo);

                String Response = isharesPageObjects3.SHARES_RESPONSE.getText();
                gl.checkForErrors(command,Response,logInfo);

                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                gl.waitForProfileLoad();

                for (int j = 1; j <= 3; j++) {  //loop for flight

                    String command2 = "N" + totalpax + COS + j; //N2Y1

                    gl.logCommand(logInfo, command2);
                    gl.sendCmdValidateResponse(command2, logInfo);
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    String response = isharesPageObjects3.SHARES_RESPONSE.getText();
                    gl.checkForErrors(command2,response,logInfo);


                    if (response.contains("ETKT ELIGIBLE") || response.contains("ADV PAX FLT ARRIVES TERMINAL") || response.contains("SS" + totalpax) || response.contains("NN" + totalpax)) {
                        for (Passenger pax1 : mPassengers.get(getDriverID())) {
                            pax1.setSegmentFlight(0, response.substring(6, 10).trim());
                            pax1.setSegmentDate(0, departuredate);
                            pax1.setCOS(COS);
                        }
                        flag = 1;
                        break;
                    }
                    else {
                        gl.logCommand(logInfo, command);
                        gl.sendCmdValidateResponse(command, logInfo);
                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                        gl.checkForErrors(command,isharesPageObjects3.SHARES_RESPONSE.getText(),logInfo);

                    }
                }
                if (flag == 1) {
                    break;
                }
            }

            logInfo.pass("Search for double availability ");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

