    public void enter_PTAThirdPartyTable(ExtentTest logInfo) {
        try {

            //  PITP/TT*      --> Displaying Entire Table
            String command = "PITP/TT*";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "THIRD PARTY FLIGHT NUMBER TRANSLATE TABLE", logInfo);

            //  PITP/TTA/TUA/N401    --> Adding to the Table
            command = "PITP/TTA/TUA/N401";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "THIRD PARTY FLIGHT NUMBER TRANSLATE TABLE", logInfo);

            //  PITP/TTA2000-2399/E01JUL21/D31DEC24/F1.2.3/TCS2000-2399/N596   -->Adding to the table
            command = "PITP/TTA2000-2399/E01JUL21/D31DEC24/F1.2.3/TCS2000-2399/N360";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command,"ITEM ADDED", "THIRD PARTY FLIGHT NUMBER TRANSLATE TABLE","OVERLAPING ITEM", logInfo);

            if(isharesPageObjects3.SHARES_RESPONSE.getText().contains("OVERLAPING ITEM"))
            {
                command = "PITP/TT*";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "THIRD PARTY FLIGHT NUMBER TRANSLATE TABLE", logInfo);

                String Response = isharesPageObjects3.SHARES_RESPONSE.getText();

                String[] responseAsRows = Response.split("\n");
                for(String rows : responseAsRows)
                {
                    if(rows.contains("360"))
                    {
                        String[] words = rows.split(" ");
                        command = "PITP/TTD "+Integer.parseInt(words[0]);
                        gl.logCommand(logInfo, command);
                        gl.sendCmdValidateResponse(command, "ITEM DELETED", logInfo);
                    }
                }

                gl.waitForProfileLoad();

                command = "PITP/TTA2000-2399/E01JUL21/D31DEC24/F1.2.3/TCS2000-2399/N360";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command,"ITEM ADDED", "THIRD PARTY FLIGHT NUMBER TRANSLATE TABLE","INVLD - OVERLAPING ITEM", logInfo);
            }


            //  PITP/TTD 1   --> Deleting from the Table
            command = "PITP/TTD 1";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "ITEM DELETED","THIRD PARTY FLIGHT NUMBER TRANSLATE TABLE", logInfo);

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

