    public void enterMVTableDisplay(ExtentTest logInfo, String originCity, String destination1City, String destination2City) {
        try {

            String command = "MV*" + originCity + destination1City;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "MARKET VALUE TABLE", logInfo);
            String response = isharesPageObjects3.SHARES_RESPONSE.getText();
            String[] rows=response.split("\n");

            String itemNum=null;
            String classAvailable=null;

            // Extract first number
            Matcher numberMatcher = Pattern.compile("\\d+").matcher(rows[5]);
            if (numberMatcher.find()) {
                itemNum = numberMatcher.group();
            }

            command = "MV*" + originCity + destination1City+"/"+itemNum;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "MARKET VALUE TABLE", logInfo);

            command = "MV*" + originCity + destination2City;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "MARKET VALUE TABLE", logInfo);
            response = isharesPageObjects3.SHARES_RESPONSE.getText();
            rows=response.split("\n");
            // Extract first number
            numberMatcher = Pattern.compile("\\d+").matcher(rows[5]);
            if (numberMatcher.find()) {
                itemNum = numberMatcher.group();
            }

            // Extract first alphabet
            Matcher letterMatcher = Pattern.compile("[A-Za-z]").matcher(rows[5]);
            if (letterMatcher.find()) {
                classAvailable = letterMatcher.group();
            }

            command = "MV*" + originCity + destination2City+"/"+itemNum;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "MARKET VALUE TABLE", logInfo);

            command = "MV*" + originCity + destination2City+"/"+classAvailable;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "MARKET VALUE TABLE", logInfo);


        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

