    public void enterKCCommandRelatedToMarketingOptionsTable(ExtentTest logInfo, String entry) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String flight = pax.getSegmentFlight(0);
            String StartDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String EndDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0) + 100);

            if (entry.equalsIgnoreCase("KC_C_A_F")) {
                //KC/C/A/F.302
                String command = "KC/C/A/F." + flight;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "CM - MARKETING REACCOMMODATION OPTION TABLE", "OVERLAP OR DUPE ITEM", logInfo);
            } else if (entry.equalsIgnoreCase("KC_C_T")) {
                //KC/C/T.360
                String command = "KC/C/T.360";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "REAC IF", flight, logInfo);
            } else if (entry.equalsIgnoreCase("KC_C_OPT")) {
                //KC/C/OPT*
                String command = "KC/C/OPT*";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "MARKETING REACCOMMODATION OPTION TABLE", logInfo);
            } else if (entry.equalsIgnoreCase("KC_STATUS")) {
                //KC/C/STATUS
                String command = "KC/C/STATUS";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "MARKETING REACCOM STATUS", logInfo);
            } else if (entry.equalsIgnoreCase("KC_RPT")) {
                //KC/C/RPT*
                String command = "KC/C/RPT*";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "MARKETING REACCOM PNR DISTRIBUTION","COLLECTION NOT COMPLETE", logInfo);

            } else if (entry.equalsIgnoreCase("KC_F")) {

                gl.logCommand(logInfo, "KC/C/OPT*");
                gl.sendCmdValidateResponse("KC/C/OPT*", "MARKETING REACCOMMODATION OPTION TABLE", logInfo);
                String Response = isharesPageObjects3.SHARES_RESPONSE.getText();
                String indexNumber = "";

                int i = 0;

                int index = Response.indexOf(flight + "-");
                indexNumber = Response.substring(index - 20, index - 16).trim();
                System.out.println(indexNumber);

                //  KC/C/C001/F.302
                String command = "KC/C/C" + indexNumber + "/F." + flight;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "MARKETING REACCOMMODATION OPTION TABLE", logInfo);
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


