    public void flightAvailabilityWithoutSpecifyingOrigin(ExtentTest logInfo, String destinationCity, String departureTime) {                // This method is only to display the availability and to not select any flight
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String command = null;

            if (departureTime.equalsIgnoreCase("")) {
//                A LAX
                command = "A " + destinationCity;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, pax.getPOS(), destinationCity, logInfo);
            } else if (departureTime.equalsIgnoreCase("A") || departureTime.equalsIgnoreCase("P")) {
//                A ORD P
                command = "A " + destinationCity + " " + departureTime;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, pax.getPOS(), destinationCity, logInfo);
            } else {
//               A EWR 0800A
                command = "A " + destinationCity + " 0" + departureTime;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, pax.getPOS(), destinationCity, logInfo);
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
        }
    }

