    public void deleteACarrierEntryFromTheTable(ExtentTest logInfo) {
        try {
            //     K-T-PARTNER/*/FQR/**                  //display the table
            String command = "K-T-PARTNER/*/FQR/**";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "STAR ALLIANCE", logInfo);

            String response = isharesPageObjects3.SHARES_RESPONSE.getText();
            String[] rows = response.split("\n");
            String carrierCode = rows[2].substring(0, 3);

//             K-T-PARTNER/D/FQR/UA
            command = "K-T-PARTNER/D/FQR/" + carrierCode;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "PARTNER DATA DELETED", logInfo);

//            K-T-PARTNER/A/FQR/NH|CM/01/01           //adding back the deleted carrier code
            command = "K-T-PARTNER/A/FQR/" + carrierCode + "|CM/01/01";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "PARTNER DATA ADDED", logInfo);

            command = "K-T-PARTNER/*/FQR/**";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, carrierCode, logInfo);

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
        }
    }


