    public void toFinalizeModificationInAPISCONTROLTable(ExtentTest logInfo, String Status) {
        try {

//          PAAF#M
            String command = "PAAF#M";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "-Y/N-", logInfo);

            String Response = isharesPageObjects3.SHARES_RESPONSE.getText();


            if (Response.contains("-Y/N-")) {
                if (Status.contains("REJECT")) {
//              PAAF#M-Y/N-N
                    command = "PAAF#M-Y/N-N";
                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, "OK", "TABLE MODIF-NOT FINALIZED", logInfo);

                } else if (Status.contains("ACCEPT")) {

//                    PAAF#M-Y/N-Y
                    command = "PAAF#M-Y/N-Y";
                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, "OK", "FINALIZED", logInfo);
                }

            }
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

