    public void enterBFCommandToPrintBoardingPass(ExtentTest logInfo, String BoardingType) {

        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String flight = pax.getSegmentFlight(0);
            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String origin = pax.getSegmentOriginCity(0);
            int totalpax = mPassengers.get(getDriverID()).size();
            String Command ;


            //6:BF243/27JANPTY-YOU/YOURS
            if (BoardingType.equalsIgnoreCase("ForceBoarding")) {
                for (int i = 0; i < totalpax; i++) {

                    pax = mPassengers.get(getDriverID()).get(i);

                    if (pax.getPaxType().equalsIgnoreCase("INF")) {
                        Command = "6:BF" + flight + "/" + date + origin + "-" + pax.getAccompaniedPaxDetails().getfName() + "/" + pax.getAccompaniedPaxDetails().getlName();
                        gl.logCommand(logInfo, Command);
                        gl.sendCmdValidateResponse(Command, pax.getfName(), "FORCE PRINT BOARDING PASSES", logInfo);

                    } else if(pax.getPaxType().equalsIgnoreCase("NRPS")){
                        Command = "6:BF" + flight + "/" + date + origin + "-" + pax.getfName() + "/" + pax.getlName();
                        gl.logCommand(logInfo, Command);
                        gl.sendCmdValidateResponse(Command, pax.getfName(), "FORCE PRINT BOARDING PASSES", logInfo);

                    }else if(pax.getPaxType().equalsIgnoreCase("FQTV")){
                        Command = "6:BF" + flight + "/" + date + origin + "-" + pax.getfName() + "/" + pax.getlName();
                        gl.logCommand(logInfo, Command);
                        gl.sendCmdValidateResponse(Command, pax.getfName(), "FORCE PRINT BOARDING PASSES", logInfo);

                    }
                    else {
                        Command = "6:BF" + flight + "/" + date + origin + "-" + pax.getfName() + "/" + pax.getlName();
                        gl.logCommand(logInfo, Command);
                        gl.sendCmdValidateResponse(Command, pax.getfName(), "FORCE PRINT BOARDING PASSES", logInfo);

                    }
                }
            }
            else if (BoardingType.equalsIgnoreCase("ThruBoarding")) {

                for (int i = 0; i < totalpax; i++) {

                    pax = mPassengers.get(getDriverID()).get(i);

                    Command = "6:BF" + flight + "/" + date + origin + "-" + pax.getfName() + "/" + pax.getlName();

                    gl.logCommand(logInfo, Command);
                    gl.sendCmdValidateResponse(Command,"BOARDING PASSES ISSUED", "STBY BOARDING PASSES ISSUED", pax.getfName(),  logInfo);

                }
            }
            else if (BoardingType.equalsIgnoreCase("TestBoardingWithDateCity")) {
                //6:BT332/07DECPTY-GOLD/PEDRO
                for (int i = 0; i < totalpax; i++) {
                    pax = mPassengers.get(getDriverID()).get(i);
                    if (pax.getPaxType().equalsIgnoreCase("INF")) {
                        Command = "6:BT" + flight + "/" + date + origin + "-" + pax.getAccompaniedPaxDetails().getfName() + "/" + pax.getAccompaniedPaxDetails().getlName();
                        gl.logCommand(logInfo, Command);
                        gl.sendCmdValidateResponse(Command, pax.getfName(), "TEST BOARDING PASS", logInfo);
                    }
                    else if(pax.getPaxType().equalsIgnoreCase("NRPS")){
                        Command = "6:BT" + flight + "/" + date + origin + "-" + pax.getfName() + "/" + pax.getlName();
                        gl.logCommand(logInfo, Command);
                        gl.sendCmdValidateResponse(Command, pax.getfName(), "TEST BOARDING PASS", logInfo);
                    }
                    else if(pax.getPaxType().equalsIgnoreCase("FQTV")){
                        Command = "6:BT" + flight + "/" + date + origin + "-" + pax.getfName() + "/" + pax.getlName();
                        gl.logCommand(logInfo, Command);
                        gl.sendCmdValidateResponse(Command, pax.getfName(), "TEST BOARDING PASS", logInfo);
                    }
                    else {
                        Command = "6:BT" + flight + "/" + date + origin + "-" + pax.getfName() + "/" + pax.getlName();
                        gl.logCommand(logInfo, Command);
                        gl.sendCmdValidateResponse(Command, pax.getfName(), "TEST BOARDING PASS", logInfo);
                    }
                }
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            org.junit.Assert.fail("This step failed.. so stopping...");
        }

    }


