    public void displayCodeshareFltNoAndDisplaySpecificFltNoInTable(ExtentTest logInfo) {
        try {
//                2CS*
            ArrayList<String> flightNumber = new ArrayList<>();

            displayCodeshareFltNo(logInfo);

//               2CS*170
            String response = isharesPageObjects3.SHARES_RESPONSE.getText();
            String[] rows = response.split("\n");

            for (int i = 3; i < rows.length; i++) {
                if (i == 7)
                    break;

                String[] temp = rows[i].split(" ");
                String fltNumber = temp[3];
                flightNumber.add(fltNumber);
            }
            System.out.println(flightNumber);

            for (String fltNo : flightNumber) {
                String command = "2CS*" + fltNo;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, fltNo, "FLT  CODESHARE PARTNERS", logInfo);
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

