    public void entercommandRestrictionTable(ExtentTest logInfo, String command) {
        try {

            //         6:CLRI
            gl.logCommand(logInfo, command);

            if (command.contains("6:CLR*")) {
                gl.sendCmdValidateResponse(command, "ASA/ABP RESTRICTION TABLE", "CUT OFF TIME", logInfo);
            }
            else if (command.contains("CLRI")) {
                int i=0;
                do
                {
                    isharesPageObjects3.COMMAND_INPUTAREA_ISHARES.click();
                    isharesPageObjects3.COMMAND_INPUTAREA_ISHARES.sendKeys(command);
                    isharesPageObjects3.SEND_ISHARES.click();
                    gl.waitForPageReload(getDriver(),isharesPageObjects3.SHARES_RESPONSE,PAGE_LOAD_TIMEOUT);
                    gl.logResponse(logInfo, isharesPageObjects3.SHARES_RESPONSE.getText());
                    if(i++>10)
                        break;
                }while(isharesPageObjects3.SHARES_RESPONSE.getText().contains("TABLE BEING MODIFIED"));

                Assert.assertTrue(isharesPageObjects3.SHARES_RESPONSE.getText().contains("ASA/ABP RESTRICTION TABLE") || isharesPageObjects3.SHARES_RESPONSE.getText().contains("TABLE INITIALIZED"),"Table is being modified by some other test case");

            }
            else if (command.contains("CLRF")) {
                gl.sendCmdValidateResponse(command, "TABLE FINALIZED", logInfo);
            }
            else if (command.contains("CLRX")) {
                gl.sendCmdValidateResponse(command, "TABLE CANCELLED", logInfo);
            }
            else if (command.contains("SORT")) {
                if (isharesPageObjects3.SHARES_RESPONSE.getText().contains("TABLE NOT INITIALIZED")) {
                    gl.sendCmdValidateResponse(command, "TABLE NOT INITIALIZED", logInfo);
                } else {
                    gl.sendCmdValidateResponse(command, "ASA/ABP RESTRICTION TABLE", "CLASS PERCENTAGES  A-100", logInfo);
                }
            }
            else if (command.contains("CLAH") || command.contains("CLRT"))
            {
                if (isharesPageObjects3.SHARES_RESPONSE.getText().contains("TABLE NOT INITIALIZED")) {
                    gl.sendCmdValidateResponse(command, "TABLE NOT INITIALIZED", logInfo);
                } else {
                    gl.sendCmdValidateResponse(command, "OLD", "NEW", logInfo);
                }
            }

        } catch (AssertionError | Exception e) {

            if(!command.contains("6:CLR*") && !command.contains("CLRX") )
                gl.sendCmdValidateResponse(command, "TABLE CANCELLED", logInfo);

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");

        }

    }

