            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "BOOKING COMPARTMENT PROFILE TABLE", logInfo);

            // KJ * 360 / 23SEP88-7OCT89/1234567
            command = enterKJ_Command(logInfo, " * " + flight + "/" + dateWithYear + "-" + dateWithYear2 + "/1234567");
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "BOOKING COMPARTMENT PROFILE TABLE", logInfo);

            // TCRC01/KJ*600/21DEC23
            command = enterTCR_Command(logInfo, "C01/KJ*600/" + dateWithYear);
