            gl.sendCmdValidateResponse(command, "MSG SENT", logInfo);


            // TCRC01/KJ*600/21DEC88-7JAN89
            command = enterTCR_Command(logInfo, "C01/KJ*600/" + dateWithYear + "-" + dateWithYear2);
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "ITEM NOT IN TBL", logInfo);

            // TCRC01/KJ*600/21DEC88-7JAN89/57
