    public void chooseAClassSoAsToMakeAPassengerWaitlisted(ExtentTest logInfo) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String classOfService = null;
            boolean flag = false;

//               VIX360/10DEC
            String command = "VIX" + pax.getSegmentFlight(0) + "/" + gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "BRDOFF SEATS AVAILABLE MATRIX", logInfo);

            String response = isharesPageObjects3.SHARES_RESPONSE.getText();
            String[] rows = response.split("\n");

            for (int i = 3; i < rows.length; i++) {
                if (rows[i].contains("000WL") || rows[i].contains("-01WL")) {
                    String[] text = rows[i].split(" ");
                    for (int j = 0; j < text.length; j++) {
                        if (text[j].equalsIgnoreCase("000WL") || rows[i].contains("-01WL")) {
                            classOfService = text[j - 2];
                            System.out.println(classOfService);
                            pax.setCOS(classOfService);
                            flag = true;
                            break;
                        }
                    }
                }
                if (flag)
                    break;
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

