            gl.sendCmdValidateResponse(displayCommand, "TELETYPE COHOST", logInfo);
            if (isharesPageObjects3.SHARES_RESPONSE.getText().equalsIgnoreCase("ITEM NOT IN TBL")) {
                if (CarrierCode.equalsIgnoreCase("1S"))
                    CarrierCode = "1A";
                else
                    CarrierCode = "1S";

                displayCommand = "Q*COHOST-*" + CarrierCode;
                gl.sendCmdValidateResponse(displayCommand, "SEAMLESS PARTNER CONTROL TABLE", logInfo);
            }
            mPassengers.get(getDriverID()).get(0).setCountryCode(CarrierCode);
            String primaryQueueCode = isharesPageObjects3.SHARES_RESPONSE.getText().substring(110, 114).trim();
            mPassengers.get(getDriverID()).get(0).setFleetNumber(primaryQueueCode);

            ExtentReportListener.getExtent().createNode(new GherkinKeyword("And"), "I activated primary and secondary queue ");
            logInfo.pass("I activated primary and secondary queue");
            activatePrimarySecondaryQueue(logInfo, primaryQueueCode);

            ExtentReportListener.getExtent().createNode(new GherkinKeyword("And"), "I displayed primary and secondary queue ");
            logInfo.pass("I displayed primary and secondary queue");
            displayPrimarySecondaryQueue(logInfo, primaryQueueCode);

