            if (!gl.existElement(itineraryXPATH))
                Assert.fail("RECORD LOCATOR DOESNT EXIST IN XML");
            else {
                gl.scrollTo(itineraryXPATH.get(0));
                logInfo.pass("RECORD LOCATOR exists").addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }

            itineraryXPATH = getDriver().findElements(By.xpath("//*[contains(text(),'SDSTOOLS.PNR5.TICKET_ITMS')]"));
            if (!gl.existElement(itineraryXPATH))
                Assert.fail("TICKET INFO DOESNT EXIST IN XML");
            else {
                gl.scrollTo(itineraryXPATH.get(0));
                logInfo.pass("TICKET INFO exists").addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }

            itineraryXPATH = getDriver().findElements(By.xpath("//*[contains(text(), 'E_TICKET_IND')]"));
            if (!gl.existElement(itineraryXPATH))
                Assert.fail("COS DOESNT EXIST IN XML");
            else {
                gl.scrollTo(itineraryXPATH.get(0));
                logInfo.pass("COS exists").addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }

            itineraryXPATH = getDriver().findElements(By.xpath("//*[contains(text(), 'SDSTOOLS.PNR5.SEGMENT_ITMS')]"));
