    public void enter6BFCommand(ExtentTest logInfo) {
        try {

            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String flight = pax.getSegmentFlight(0);
            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String origin = pax.getSegmentOriginCity(0);
            String fName = pax.getfName();
            String lName = pax.getlName();

//            6-BF404/06MARPTY-COKE/COOL
            String command = "6-BF" + flight + "/" + date + origin + "-" + fName + "/" + lName;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "FORCE PRINT BOARDING PASSES", "PRINTER NOT ASSIGNED", "MULTIPLE ITEMS",logInfo);

            System.out.println("cmd : " + command);

            if (isharesPageObjects3.SHARES_RESPONSE.getText().contains("PRINTER NOT ASSIGNED")) {
                String printerCommand = "6-CQA/B-3F023B.ATB2";
                gl.logCommand(logInfo, printerCommand);
                gl.sendCmdValidateResponse(printerCommand, "PRINTER ASSIGNED", logInfo);
                gl.sendCmdValidateResponse(command, "FORCE PRINT BOARDING PASSES", logInfo);
            }
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

