    public void changeThePassengerNameAfterASA(ExtentTest logInfo, String index) {
        try {
//                   -1@POP/SAM
            Passenger pax = mPassengers.get(getDriverID()).get(0);

            Faker fname = new Faker(new Locale("en-US"));
            String FirstName = "A"+fname.name().firstName();  //Appended A to ensure always after sorting also the pax remains at 1st Position
            String LastName = "A"+fname.name().lastName();

            String command = "-" + index + "@" + FirstName + "/" + LastName;

            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, command.toUpperCase(), logInfo);

            logInfo.pass("I change the name of the passenger");

            gl.logCommand(logInfo, saveAndRetrieve);
            gl.sendCmdValidateResponse(saveAndRetrieve, "6P#ER *", FirstName.toUpperCase(), "NOTE - TRANSACT WILL UNSEAT PSGR", logInfo);

            gl.sendCmdIfRequired(endAndretrieve, FirstName.toUpperCase(), logInfo);

            String response = isharesPageObjects3.SHARES_RESPONSE.getText();
            Assert.assertTrue(response.contains(FirstName.toUpperCase() + "/" + LastName.toUpperCase()) || response.contains("NOTE - TRANSACT WILL UNSEAT PSGR"));

            if (response.contains("NOTE - TRANSACT WILL UNSEAT PSGR")) {

                gl.logCommand(logInfo,endAndretrieve);
                gl.sendCmdValidateResponse(endAndretrieve, pax.getPnr(), logInfo);
            }

//           Update the Name for 1st Pax in Framework
             pax.setfName(FirstName.toUpperCase());
             pax.setlName(LastName.toUpperCase());

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

