            String originCity = pax.getSegmentOriginCity(0);

            String command = "6:LR" + flightNo + "/" + startDate + originCity;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "002-OK-", "RESTRICTED TO CONTROLING STATION", logInfo);

