    public void fs5838RunTheInternationalSalesIndicatorEntryShares(ExtentTest logInfo, String Entry) {
        try {

            Passenger pax = mPassengers.get(getDriverID()).get(0);
            //FC#CCALC FARE END#Y2175.00/X33.00#-Y1#E1PANELTY
            String command = "FC|CCALC FARE END|Y2175.00/X33.00|-Y1|E1PANELTY";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "*", logInfo);

            //FI#SOTO
            if (Entry.equalsIgnoreCase("SOTO")) {
                command = "FI|SOTO";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "*", logInfo);
            } else if (Entry.equalsIgnoreCase("INSERTED")) {
                //FI1#R1FAREQUOTEINSERTED
                command = "FI1|R1FAREQUOTEINSERTED";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "*", logInfo);
            } else if (Entry.equalsIgnoreCase("B20K")) {
                command = "FI|B20K";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "*", logInfo);
            } else if (Entry.equalsIgnoreCase("B2PC")) {
                command = "FI|B2PC";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "*", "NO FILED/WORK QUOTE EXISTS", logInfo);
            } else if (Entry.equalsIgnoreCase("CASH")) {
                command = "FI|$CASH";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "*", logInfo);
            }
            //FF
            command = "FF";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "FARE QUOTE  1 FILED", logInfo);

            gl.logCommand(logInfo, "6P#ER");
            gl.sendCmdValidateResponse("6P#ER", pax.getPnr(), "*FQ","MODIFY REC", logInfo);
            gl.sendCmdIfRequired("ER", pax.getPnr(), logInfo);

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

