    public void enter6FM_verifySharesentries(ExtentTest logInfo, String transactionType) {
        try {

            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String airline = pax.getAirline(0);
            String origin = pax.getSegmentOriginCity(0);
            String destination = pax.getSegmentDestinationCity(0);
            String flight = pax.getSegmentFlight(0);
            String StartDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String command = "";

            if (transactionType.equals("Level 1 Display")) {
                //            6:FM1/LAX
                command = "6:FM1/" + origin;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "LEVEL 1", logInfo);
            } else if (transactionType.equals("Level 2 Display")) {
                //            6:FM1/LAX
                command = "6:FM2/" + destination;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "LEVEL 2", logInfo);
            } else if (transactionType.equals("Subsequent Level 1 or 2 Display")) {
                //            6:FM-T
                command = "6:FM-T";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "PREVIOUS LEVEL 1 OR 2 DISPLAY", logInfo);

                //            6:FM-B
                command = "6:FM-B";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "PREVIOUS LEVEL 1 OR 2 DISPLAY", logInfo);
            } else if (transactionType.equals("Level 3 Display")) {
                //            6:FM3/PTY*120STD
                command = "6:FM3/" + origin + "*" + flight + "STD";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "STD", logInfo);
            } else if (transactionType.equals("Flight Check-In Details")) {
                //            6:FM3/PTY*120FCD
                command = "6:FM3/" + origin + "*" + flight + "FCD";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "FLIGHT CHECK-IN DETAILS - FCD", logInfo);
            } else if (transactionType.equals("Weight and Balance Requirements") || transactionType.equals("Outgoing Teletype Messages")) {
                //            6:FM3/PTY*120MSG
                command = "6:FM3/" + origin + "*" + flight + "MSG";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "IATA OUTGOING MESSAGES - MSG", logInfo);
            } else if (transactionType.equals("Flight Closure Breakdown")) {
                //            6:FM3/PTY*120FCB
                command = "6:FM3/" + origin + "*" + flight + "FCB";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "FLIGHT CLOSURE BREAKDOWN", logInfo);
            } else if (transactionType.equals("Control Sets/Printers")) {
                //            6:FM3/PTY*120CTL
                command = "6:FM3/" + origin + "*" + flight + "CTL";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "CONTROL SETS/PRINTERS - CTL", logInfo);
            } else if (transactionType.equals("Miscellaneous Flight Data")) {
                //            6:FM3/PTY*120MIC
                command = "6:FM3/" + origin + "*" + flight + "MIC";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "MISCELLANEOUS FLIGHT DATA - MIC", logInfo);
            } else if (transactionType.equals("Catering Information")) {
                //            6:FM3/PTY*120CAT
                command = "6:FM3/" + origin + "*" + flight + "CAT";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "FUNCTION NOT SUPPORTED CAT", logInfo);
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void enter6CG_DisplayRemarks(ExtentTest logInfo, String remarksType) {
        try {

            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String origin = pax.getSegmentOriginCity(0);
            String flight = pax.getSegmentFlight(0);
            String StartDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String EndDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0) + 2);

            //            6:CG302/10APRPTY*#ALL
            String command = "6:CG" + flight + "/" + StartDate + origin + "*#ALL";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, logInfo);
            if (isharesPageObjects3.SHARES_RESPONSE.getText().contains("NO FLIGHT INFORMATION EXISTS")) {
                gl.logResponse(logInfo, "NO FLIGHT INFORMATION EXISTS");

                //add remarks
                // 6:CG234/16AUGLAX \n FLT DLYD BY 2 HOURS.
                command = "6:CG" + flight + "/" + StartDate + origin + "\nFLIGHT DELAYED";
                addAMessageIntoTEXTAREA(logInfo, command, "FLIGHT INFORMATION");
                gl.logResponse(logInfo, "Added Board Point Remark");

                // 6:CG234/16AUGLAX#FLT \n FLT DLYD BY 2 HOURS.
                command = "6:CG" + flight + "/" + StartDate + origin + "#FLT\nFLIGHT DELAYED";
                addAMessageIntoTEXTAREA(logInfo, command, "FLIGHT INFORMATION");
                gl.logResponse(logInfo, "Added Flight Remark");

            }

            if (remarksType.equals("All Active Remarks, This Board Point")) {
                //            6:CG234/16AUGLAX*
                command = "6:CG" + flight + "/" + StartDate + origin + "*";
                ;
                gl.sendCmdValidateResponse(command, "FLIGHT INFORMATION", logInfo);
            } else if (remarksType.equals("One Active Remark, This Board Point")) {
                //            6:CG234/16AUGLAX*1
                command = "6:CG" + flight + "/" + StartDate + origin + "*1";
                ;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "FLIGHT INFORMATION", logInfo);
            } else if (remarksType.equals("All Active Board Point and Flt Remarks")) {
                //            6:CG234/16AUGLAX*#ALL
                command = "6:CG" + flight + "/" + StartDate + origin + "*#ALL";
                ;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "FLIGHT INFORMATION", logInfo);
            } else if (remarksType.equals("One Active Flight Remark")) {
                //            6:CG234/16AUGLAX*1#FLT
                command = "6:CG" + flight + "/" + StartDate + origin + "*01#FLT";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "FLIGHT INFORMATION", logInfo);
            } else if (remarksType.equals("All Flight Remarks")) {
                //            6:CG234/16AUGLAX*#FLT
                command = "6:CG" + flight + "/" + StartDate + origin + "*#FLT";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "FLIGHT INFORMATION", logInfo);
            } else if (remarksType.equals("Remarks History, This Board Point")) {
                //            6:CG234/16AUGLAX*H
                command = "6:CG" + flight + "/" + StartDate + origin + "*H";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "FLIGHT INFORMATION", logInfo);
            } else if (remarksType.equals("Remarks History, Flt and All Board Points")) {
                //            6:CG234/16AUGLAX*H#ALL
                command = "6:CG" + flight + "/" + StartDate + origin + "*H#ALL";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "FLIGHT INFORMATION", logInfo);
            } else if (remarksType.equals("Change Flight Remark")) {
                //            6:CG234/16AUGLAX@3#FLT \n FLT DLYD BY 2 HOURS.
                command = "6:CG" + flight + "/" + StartDate + origin + "@01#FLT\nFLT DLYD BY 2 HOURS.";
                addAMessageIntoTEXTAREA(logInfo, command, "FLIGHT INFORMATION");
                gl.logResponse(logInfo, "Flight Remark changed");
            } else if (remarksType.equals("All Active Remarks, This Date Range and Board Point")) {
                //            6:CGS234/16AUG-17AUGLAX*
                command = "6:CGS" + flight + "/" + StartDate + "-" + EndDate + origin + "*";
                ;
                gl.sendCmdValidateResponse(command, "NOT AUTHORIZED USER", logInfo);

            }
            //cancel remarks
            //            6:CG234/16AUGLAX@1
            command = "6:CG" + flight + "/" + StartDate + origin + "@1";
            ;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "FLIGHT INFORMATION", logInfo);

            if (!remarksType.equals("Change Flight Remark")) {
                //            6:CG234/16AUGLAX@1#FLT
                command = "6:CG" + flight + "/" + StartDate + origin + "@1#FLT";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "FLIGHT INFORMATION", logInfo);
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

