    public void enterPCommand(ExtentTest logInfo) {

        try {
            // 2P302/09JUL OUT PTY 0700A
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String originCity = pax.getSegmentOriginCity(0);
            String flight = pax.getSegmentFlight(0);
            String StartDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String DepartFlightTime = pax.getSegmentDepartureTime(0);

            if (DepartFlightTime.length() == 4) {
                DepartFlightTime = "0" + pax.getSegmentDepartureTime(0);
            }

            String Command = "2P" + flight + "/" + StartDate + " OUT " + originCity + " " + DepartFlightTime;
            gl.logCommand(logInfo, Command);
            gl.sendCmdValidateResponse(Command, "*", logInfo);

            Command = "2P" + flight + "/" + StartDate + " ON " + originCity + " " + DepartFlightTime;
            gl.logCommand(logInfo, Command);
            gl.sendCmdValidateResponse(Command, "*", logInfo);

            Command = "2P" + flight + "/" + StartDate + " OUT " + originCity + " " + DepartFlightTime;
            gl.logCommand(logInfo, Command);
            gl.sendCmdValidateResponse(Command, "RPLCD FLWG MSG", logInfo);

            //    2360/09MAY
            String checkFlightStatus = "2" + flight + "/" + StartDate;
            logInfo.pass("I am checking the flight status");
            gl.logCommand(logInfo, checkFlightStatus);
            gl.sendCmdValidateResponse(checkFlightStatus, "ON", logInfo);

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


