    public void enter6Z_IdentifyDupeSeats(ExtentTest logInfo) {
        try {

            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String flight = pax.getSegmentFlight(0);
            String StartDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String origin = pax.getSegmentOriginCity(0);
            String destination = pax.getSegmentDestinationCity(0);

            //             6-ZM360/10AUGPTY
            String command = "6-ZM" + flight + "/" + StartDate + origin;
            verify6Z_IdentifyDupeSeats(logInfo, command, "ACI MAP- UTILITYSTARTING", "");

            //             6-ZP302/1SEPPTY.Y/LAX#9A
            command = "6-ZP" + flight + "/" + StartDate + origin + ".Y/" + destination + "#9A";
            verify6Z_IdentifyDupeSeats(logInfo, command, "002-OK", "ENTRY NOT ACTIONED -   9A PREVIOUSLY REMOVED");

            //             6-ZP302/1SEPPTY.Y/LAX#@9A
            command = "6-ZP" + flight + "/" + StartDate + origin + ".Y/" + destination + "#@9A";
            verify6Z_IdentifyDupeSeats(logInfo, command, "002-OK", "ENTRY NOT ACTIONED -   9A PREVIOUSLY REMOVED");

            //             OCM*SAXJ/MAPS/STATUS
            command = "OCM*SAXJ/MAPS/STATUS";
            verify6Z_IdentifyDupeSeats(logInfo, command, "MAP- UTILITY STATUS", "");

            gl.ignoreTRNS(logInfo);

            //             6-ZM360/10AUGPTY
            command = "6-ZM" + flight + "/" + StartDate + origin;
            verify6Z_IdentifyDupeSeats(logInfo, command, "ACI MAP- UTILITYSTARTING", "");

            //             6-ZP302/1SEPPTY.Y/LAX#9A
            command = "6-ZP" + flight + "/" + StartDate + origin + ".Y/" + destination + "#9A";
            verify6Z_IdentifyDupeSeats(logInfo, command, "002-OK", "ENTRY NOT ACTIONED -   9A PREVIOUSLY REMOVED");

            //             6-ZP302/1SEPPTY.Y/LAX#10A
            command = "6-ZP" + flight + "/" + StartDate + origin + ".Y/" + destination + "#10A";
            verify6Z_IdentifyDupeSeats(logInfo, command, "002-OK", "ENTRY NOT ACTIONED -   10A PREVIOUSLY REMOVED");

            //             6-ZP302/1SEPPTY.Y/LAX#@10A
            command = "6-ZP" + flight + "/" + StartDate + origin + ".Y/" + destination + "#@10A";
            verify6Z_IdentifyDupeSeats(logInfo, command, "002-OK", "ENTRY NOT ACTIONED -   10A PREVIOUSLY REMOVED");

            //             6-ZM360/10AUGPTY
            command = "6-ZM" + flight + "/" + StartDate + origin;
            verify6Z_IdentifyDupeSeats(logInfo, command, "ACI MAP- UTILITYSTARTING", "");

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

