    public void enterPAHK_Displaytable(ExtentTest logInfo, String tableType) {
        try {

            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String origin = pax.getSegmentOriginCity(0);
            String destination = pax.getSegmentDestinationCity(0);
            String command = "";

            if (tableType.equals("Entire Table in cabin text table") || tableType.equals("items from Table")) {
                //            PAHK*
                if (tableType.equals("Entire Table in cabin text table")) {
                    command = "PAHK*";
                } else {
                    command = "PAHK*B" + origin + "|O" + destination;
                }

                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, logInfo);

                if (isharesPageObjects3.SHARES_RESPONSE.getText().contains("FIRST")) {
                    Assert.assertTrue(isharesPageObjects3.SHARES_RESPONSE.getText().contains("FIRST"));
                } else {
                    command = "PAHKA#B" + origin + "/O" + destination + "#INTN#BUSY#N1#THRUN#C1FIRST#C1ECONOMY#C1BUSINESS#PUNITED LARARIS";
                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, "OK- ITEM ADDED", logInfo);

                    command = "PAHK*";
                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, "FIRST", logInfo);
                }

            } else if (tableType.equals("all items with seat")) {
                //            PAHK*S
                command = "PAHK*S";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, logInfo);
                if (isharesPageObjects3.SHARES_RESPONSE.getText().contains("ECONOMY PLUS SEAT TEXT")) {
                    Assert.assertTrue(isharesPageObjects3.SHARES_RESPONSE.getText().contains("ECONOMY PLUS SEAT TEXT"));
                } else {
                    command = "PAHKA#S/Q#CECONOMYPLUS";
                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, "OK- ITEM ADDED", logInfo);

                    command = "PAHK*S";
                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, "ECONOMY PLUS SEAT TEXT", logInfo);
                }
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

