    public void modifyACIStatusRemarksSharesEntries(ExtentTest logInfo) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String StartDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String origin = pax.getSegmentOriginCity(0);

            //6:CG136/05MARPTY*
            String command = "6:CG" + pax.getSegmentFlight(0) + "/" + StartDate + origin + "*";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "NO FLIGHT INFORMATION", "FLIGHT INFORMATION", logInfo);

            //6:CG136/05MARPTY
            command = "6:CG" + pax.getSegmentFlight(0) + "/" + StartDate + origin + "\n" + "FLIGHT DELAYED";
            gl.logCommand(logInfo, command);
            isharesPageObjects3.FORMSIZE_DROPDOWN.click();
            isharesPageObjects3.FORMSIZE_SELECT2.click();
            isharesPageObjects3.FORMSIZE_SELECT2_TEXTAREA.click();

            gl.copyCmdToClipboardAndPaste(command, isharesPageObjects3.FORMSIZE_SELECT2_TEXTAREA);
            isharesPageObjects3.SEND_ISHARES.click();

            String response = isharesPageObjects3.SHARES_RESPONSE.getText();
            Assert.assertTrue(response.contains("ADDED") || response.contains("FLIGHT DELAYED"));

            //6:CG136/05MARPTY@1
            command = "6:CG" + pax.getSegmentFlight(0) + "/" + StartDate + origin + "@1" + "\n" + "THANK YOU";
            gl.logCommand(logInfo, command);
            isharesPageObjects3.FORMSIZE_DROPDOWN.click();
            isharesPageObjects3.FORMSIZE_SELECT2.click();
            isharesPageObjects3.FORMSIZE_SELECT2_TEXTAREA.click();

            gl.copyCmdToClipboardAndPaste(command, isharesPageObjects3.FORMSIZE_SELECT2_TEXTAREA);
            isharesPageObjects3.SEND_ISHARES.click();

            response = isharesPageObjects3.SHARES_RESPONSE.getText();
            Assert.assertTrue(response.contains("CANCELLED") || response.contains("THANK YOU"));

            //6:CG120/05DECPTY@2
            command = "6:CG" + pax.getSegmentFlight(0) + "/" + StartDate + origin + "@2" + "\n" + "THANK YOU";
            gl.logCommand(logInfo, command);
            isharesPageObjects3.FORMSIZE_DROPDOWN.click();
            isharesPageObjects3.FORMSIZE_SELECT2.click();
            isharesPageObjects3.FORMSIZE_SELECT2_TEXTAREA.click();

            gl.copyCmdToClipboardAndPaste(command, isharesPageObjects3.FORMSIZE_SELECT2_TEXTAREA);
            isharesPageObjects3.SEND_ISHARES.click();

            response = isharesPageObjects3.SHARES_RESPONSE.getText();
            Assert.assertTrue(response.contains("CANCELLED") || response.contains("THANK YOU"));

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

