    public void KKUTILInventoryDiscrepancies449(ExtentTest logInfo, String entry) {

        try {
            //KKUTIL/STATUS
            if (entry.equalsIgnoreCase("STATUS")) {
                String command = "KKUTIL/" + entry;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "015INVLD CLASS", logInfo);

            } else if (entry.equalsIgnoreCase("HOLD")) {
                String command = "KKUTIL/" + entry;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "015INVLD CLASS", logInfo);

            } else if (entry.equalsIgnoreCase("UNHOLD")) {
                String command = "KKUTIL/" + entry;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "015INVLD CLASS", logInfo);

            } else if (entry.equalsIgnoreCase("ADJDAY/1")) {
                String command = "KKUTIL/" + entry;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "015INVLD CLASS", logInfo);

            } else if (entry.equalsIgnoreCase("ADJDAY/10")) {
                String command = "KKUTIL/" + entry;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "015INVLD CLASS", logInfo);

            } else if (entry.equalsIgnoreCase("ADJDAY/0")) {
                String command = "KKUTIL/" + entry;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "015INVLD CLASS", logInfo);
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

