    public String runThirdPartyAddEntryForThreeAirlineCodes(ExtentTest logInfo) {
        String cityCode = null;
        try {
//                    PIAT*
            String command = "PIAT*";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "IATA CITY CODE ADDRESSEE TABLE", logInfo);

            String[] cityCodes = {"LIM", "SFO", "SJO", "PTY", "MEX", "MIA", "LAX", "FLL", "EZE", "CUN", "GRU", "BOG"};

            String response = isharesPageObjects3.SHARES_RESPONSE.getText();

            for (int i = 0; i < cityCodes.length; i++) {
//            PIATUTYYZ#AM.MX.UA
                command = "PIATUT" + cityCodes[i] + "|AM.MX.UA";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "AM MX UA", "ADDED", "DUPLICATE", logInfo);

                if (!response.contains("DUPLICATE")) {
                    cityCode = cityCodes[i];
                    break;
                }
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

        return cityCode;
    }

