    public void enterK_EDToDeleteSSRFromPSCExceptionTable(ExtentTest logInfo, String SSR) {
        // K-ED/<SSR>///31JAN23-OPEN

        try {
            String command = "K-E*/" + SSR;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, SSR, logInfo);

            if (isharesPageObjects3.SHARES_RESPONSE.getText().contains(SSR)) {
                String response = isharesPageObjects3.SHARES_RESPONSE.getText();
                String dateOfSSR = null;
                for (int i = 0; i < response.split("\n").length; i++) {
                    String line = response.split("\n")[i];
                    if (line.contains(SSR)) {
                        for (int j = 0; j < line.split(" ").length; j++) {
                            String word = line.split(" ")[j];
                            if (word.contains("OPEN")) {
                                dateOfSSR = word;
                                break;
                            }
                        }
                    }
                    if (dateOfSSR != null)
                        break;
                }
                command = "K-ED/" + SSR + "///" + dateOfSSR;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "ITEMS DELETED","ITEM DELETED", logInfo);
            } else {
                logInfo.fail(SSR + " has not been added to PSC Exception table");
                Assert.fail(SSR + " has not been added to PSC Exception table");
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

