    public void enter6TMToAddMessage(ExtentTest logInfo, String msg) {
        try {
//             6:TM136/10AUGPTY-RICHARD/JAMES
//             FLIGHT DELAYED

            for (Passenger pax : mPassengers.get(getDriverID())) {
                String command = "6:TM" + mPassengers.get(getDriverID()).get(0).getSegmentFlight(0) + "/" +
                        gl.sharesFormatDateFromGUI(mPassengers.get(getDriverID()).get(0).getSegmentDate(0)) +
                        mPassengers.get(getDriverID()).get(0).getSegmentOriginCity(0) + "-" + pax.getfName() + "/" + pax.getlName() + "\n" + msg;

                gl.logCommand(logInfo, command);
                gl.sendCopiedCmdValidateResponse2(logInfo, command, "002-OK-", "MULTIPLE ITEMS");

                if (isharesPageObjects3.SHARES_RESPONSE.getText().contains("MULTIPLE ITEMS")) {
                    String response = isharesPageObjects3.SHARES_RESPONSE.getText();

                    // Checking PNR in multiple item list
                    for (int j = 0; j < 7; j++) {
                        if (response.contains(pax.getPnr())) {
                            response = isharesPageObjects3.SHARES_RESPONSE.getText();
                            break;
                        } else {
                            gl.sendCmdValidateResponse("MD", logInfo);
                            response = isharesPageObjects3.SHARES_RESPONSE.getText();
                        }
                    }

                    //Capturing ID for the PNR
                    int index = response.indexOf(pax.getPnr());
                    String indexVal = response.substring((index - 27), (index - 24)).trim();

                    //6:LTM-44
                    String MultiListCmd = "6:LTM-" + indexVal;
                    gl.logCommand(logInfo, MultiListCmd);
                    gl.sendCmdValidateResponse(MultiListCmd, "002-OK-", logInfo);

                }
            }
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

