    public void toDivideThePNRUsingThePassengersCount(ExtentTest logInfo, String Count) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);

            DividePNR:
            for (int i = 0; ; i++) {
                String command = "D" + Count;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, logInfo);

                gl.logCommand(logInfo, "6P");
                gl.sendCmdValidateResponse("6P", "6P *", logInfo);

                gl.logCommand(logInfo, "F");
                gl.sendCmdValidateResponse("F", "RECORD FILED", logInfo);
                String Response = isharesPageObjects3.SHARES_RESPONSE.getText();
                pax.setPnr2(Response.substring(13, 19));  // Stored newly created PNR in map setPnr2
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                gl.logCommand(logInfo, "6P#ER");
                gl.sendCmdValidateResponse("6P#ER", "CHANGES RESTRICTED - COMPLETE PNR DIVIDE AND ER", "6P#ER *", pax.getPnr(), logInfo);
                gl.logCommand(logInfo, "ER");
                gl.sendCmdIfRequired("ER", "RCVD-P", logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                if (isharesPageObjects3.SHARES_RESPONSE.getText().contains("SIMULT CHGS TO PNR")) {
                    gl.logCommand(logInfo, "IR");
                    gl.sendCmdValidateResponse("IR", pax.getPnr(), logInfo);

                    continue DividePNR;
                } else if (isharesPageObjects3.SHARES_RESPONSE.getText().contains("RCVD-P")) {
                    break;
                }
            }
            gl.logCommand(logInfo, "*" + pax.getPnr2());
            gl.sendCmdValidateResponse("*" + pax.getPnr2(), pax.getPnr2(), logInfo);

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void toCancelAndReinstateMisconnectPassengersFromInboundCMFlight(ExtentTest logInfo) {

        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String Flight = pax.getSegmentFlight(0);
            String ConnectingOrigin = pax.getSegmentOriginCity(0);
            String Date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));

            //6:LD360/09JANPTY#IC

            String displayList = "6:LD" + pax.getSegmentFlight(0) + "/" + gl.sharesFormatDateFromGUI(pax.getSegmentDate(0)) +
                    pax.getSegmentOriginCity(0) + "|IC";

            gl.logCommand(logInfo, displayList);
            gl.sendCmdValidateResponse(displayList, logInfo);
            gl.waitForProfileLoad();

            String response = isharesPageObjects3.SHARES_RESPONSE.getText();

            String[] Response = response.split("\n");
            String[] row = Response[3].split(" ");
            String ConnectingFlight = row[row.length-1].trim();
            if(ConnectingFlight.length() != 3){
                Response = response.split("\n");
                row = Response[5].split(" ");
                ConnectingFlight = row[row.length-1].trim();
            }
            System.out.println(ConnectingFlight);

            //6:CX138/11OCTPTY.247

            String cancelMisconnectCmd = "6:CX" + Flight + "/" + Date + ConnectingOrigin + "." + ConnectingFlight;
            gl.logCommand(logInfo, cancelMisconnectCmd);
            gl.sendCmdValidateResponse(cancelMisconnectCmd, "PAX CONNECTING FROM FLT", "SHIP NOT ASSIGNED", "ENTER FROM CONTROLLING CRT", logInfo);
            System.out.println("cmd : " + cancelMisconnectCmd);

            if (isharesPageObjects3.SHARES_RESPONSE.getText().contains("SHIP NOT ASSIGNED")) {
                isharesPage2.openFlight(logInfo, ConnectingFlight, Date, ConnectingOrigin);
                isharesPageObjects3.FORMSIZE_DROPDOWN.click();
                isharesPageObjects3.FORMSIZE_SELECT1.click();
                gl.waitForProfileLoad();
                gl.sendCmdValidateResponse(cancelMisconnectCmd, "PAX CONNECTING FROM FLT", "ENTER FROM CONTROLLING CRT", logInfo);
            }

            if (isharesPageObjects3.SHARES_RESPONSE.getText().contains("ENTER FROM CONTROLLING CRT")) {
                String command = "6-CQA" + "/" + "C***";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "ASSIGNED CONTROLLING SET FOR", "CONTROLLING SET CHANGED TO", logInfo);
                gl.sendCmdValidateResponse(cancelMisconnectCmd, "PAX CONNECTING FROM FLT", "CANCELLED", logInfo);
            }
            //            6:CX138/11OCTPTY.247|@

            String reinstateMisconnectCmd = "6:CX" + Flight + "/" + Date + ConnectingOrigin + "." + ConnectingFlight + "|@";
            gl.logCommand(logInfo, reinstateMisconnectCmd);
            gl.sendCmdValidateResponse(reinstateMisconnectCmd, "PAX CONNECTING FROM FLT", "REINSTATED", logInfo);

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

