    public void setRemarkIndexes(ExtentTest logInfo) {
        Passenger pax = mPassengers.get(getDriverID()).get(0);
        String remarkText = pax.getRemarkText();
        String indexNumber = "";

        for (int i = 0; i < 4; i++) {
            String Response = isharesPageObjects3.SHARES_RESPONSE.getText();
            if (Response.contains(remarkText)) {
                int indexValue = (Response.indexOf(remarkText) - 5);
                System.out.println(indexValue + "indexvalue");
                indexNumber = Response.substring(indexValue, indexValue + 4).replaceAll("[^0-9]", "").trim();
                System.out.println(indexNumber + "indexNumber");
                pax.setRemarkIndex(indexNumber);
                break;
            } else {
                gl.sendCmdValidateResponse("MD", logInfo);
            }
        }
    }

