    public void toRunStandbyProcessingMassSeatAssignment(ExtentTest logInfo) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String Flight = pax.getSegmentFlight(0);
            String origin = pax.getSegmentOriginCity(0);
            String Date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));

//             6:*K226/25DECPTY

            String standbyProcessCmd = "6:*K" + Flight + "/" + Date + origin;
            gl.logCommand(logInfo, standbyProcessCmd);
            gl.sendCmdValidateResponse(standbyProcessCmd, "CNT FROM PMP", "FLT NOT OPEN", "RESTRICTED TO CONTROLING STATION", logInfo);
            System.out.println("cmd : " + standbyProcessCmd);

            if (isharesPageObjects3.SHARES_RESPONSE.getText().contains("FLT NOT OPEN")) {
                isharesPage2.openFlight(logInfo, Flight, Date, origin);
                isharesPageObjects3.FORMSIZE_DROPDOWN.click();
                isharesPageObjects3.FORMSIZE_SELECT1.click();
                gl.waitForProfileLoad();
                gl.sendCmdValidateResponse(standbyProcessCmd, "CNT FROM PMP", logInfo);
            }

            if (isharesPageObjects3.SHARES_RESPONSE.getText().contains("RESTRICTED TO CONTROLING STATION")) {
                //6-CQA/C-PTY
                assignControllingAgent(logInfo);
                gl.logCommand(logInfo, standbyProcessCmd);
                gl.sendCmdValidateResponse(standbyProcessCmd, "CNT FROM PMP", logInfo);
            }

            gl.ignoreTRNS(logInfo);

//             6:KM360/06NOVPTY

            String command = "6:KM" + Flight + "/" + Date + origin;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "STANDBY BOARDING COMPLETE", "SEATS ASSIGNED", "STNDBYS PROCESSD CHKED-IN", logInfo);

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


