    public void EnterDownGradeLowerCabinCommandWithCOS(ExtentTest logInfo, String COS1) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String Origin = pax.getSegmentOriginCity(0);
            String flight = pax.getSegmentFlight(0);
            String Date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));

            for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {
                gl.ignoreTRNS(logInfo);
                pax = mPassengers.get(getDriverID()).get(0);

                //6:GV497/11JUNPTY-TEST/RIM.Y
                String command = "6:GV" + flight + "/" + Date + Origin + "-" + pax.getfName() + "/" + pax.getlName() + "." + COS1;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "SEATS ASSIGNED", "MULTIPLE ITEMS", "UNABLE PROC-MULT NAME PNR", logInfo);

                if (isharesPageObjects3.SHARES_RESPONSE.getText().contains("MULTIPLE ITEMS")) {
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    String response = isharesPageObjects3.SHARES_RESPONSE.getText();

                    // Checking PNR in multiple item list
                    for (int j = 0; j < 7; j++) {
                        if (response.contains(pax.getPnr())) {
                            response = isharesPageObjects3.SHARES_RESPONSE.getText();
                            break;
                        } else {
                            gl.sendCmdValidateResponse24("MD", logInfo);
                            response = isharesPageObjects3.SHARES_RESPONSE.getText();
                        }
                    }

                    //Capturing ID for the PNR
                    int index = response.indexOf(pax.getPnr());
                    String indexVal = response.substring((index - 27), (index - 24)).trim();

                    //6-LUG-273.Y
//                        String MultiListCmd = "6:LUG-" + indexVal + "." + UpgradeClass;
                    String MultiListCmd = "6:LGV-" + indexVal;
                    gl.logCommand(logInfo, MultiListCmd);
                    gl.sendCmdValidateResponse(MultiListCmd, "SEATS ASSIGNED", logInfo);

                }
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


    public void ToRejectMassTransferBasedOnClassOfService(ExtentTest logInfo) {
        try {
//        6:MT<New flight>/<DOJ><ORIGIN>.<OLD FIGHT>/<DOJ><ORIGIN>#C/S
//        6:MT415/03MARPTY.243/03MARPTY#C/S

            gl.ignoreTRNS(logInfo);
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String oldFlightNo = pax.getOldFlightNumber();
            String oldCOS = pax.getOldFlightCOS();

            String massTransferCmd = "6:MT" + pax.getSegmentFlight(1) + "/" + date + pax.getSegmentOriginCity(0) + "." +
                    oldFlightNo + "/" + date + pax.getSegmentOriginCity(0) + "|" + oldCOS + "/" + pax.getCOS();

            System.out.println("CMD: " + massTransferCmd);
            gl.logCommand(logInfo, massTransferCmd);
            gl.sendCmdValidateResponse(massTransferCmd, "MOVE FROM FLIGHT", "SHIP NOT ASSIGNED", logInfo);

            if (isharesPageObjects3.SHARES_RESPONSE.getText().contains("SHIP NOT ASSIGNED")) {
                isharesPageObjects3.COMMAND_INPUTAREA_ISHARES.sendKeys(Keys.CONTROL + "a" + Keys.BACK_SPACE);
                openFlight(logInfo, pax.getSegmentFlight(1), date, pax.getSegmentOriginCity(0));

                isharesPageObjects3.FORMSIZE_DROPDOWN.click();
                isharesPageObjects3.FORMSIZE_SELECT1.click();
                gl.waitForProfileLoad();

                gl.logCommand(logInfo, massTransferCmd);
                gl.sendCmdValidateResponse(massTransferCmd, "MOVE FROM FLIGHT  " + pax.getSegmentFlight(0) + " TO FLIGHT  " + pax.getSegmentFlight(1), logInfo);
            }

            isharesPageObjects3.FORMSIZE_DROPDOWN.click();
            isharesPageObjects3.FORMSIZE_SELECT2.click();
            isharesPageObjects3.FORMSIZE_SELECT2_TEXTAREA.sendKeys(Keys.CONTROL + "a" + Keys.BACK_SPACE);

            System.out.println("Mass transfer command : " + massTransferCmd);

            String rejectOrAccept = "PLEASE CONFIRM -Y/N- N";
            String MassTransfer = massTransferCmd + "\n" + rejectOrAccept;
            System.out.println("MassTransfer: \n" + MassTransfer);

            gl.sendCopiedCmdValidateResponse2(logInfo, MassTransfer, "TRANSFER ABORTED");
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

