    public void removeExceptionForSSR(ExtentTest logInfo, String SSR) {
        try {

            isharesPage2.showPSCExceptionTableForSSR(logInfo,SSR);

            String onlyAlphaNumericRegex ="^(?=.*[A-Za-z])(?=.*\\d)[A-Za-z0-9]+$"; //only for alphanumeric
            String alphaNumericREGEX = "^[a-zA-Z0-9]*$"; // includes both only alphanumeric and only alphabetic as well
            String numericREGEX = "^[0-9]+$"; //only digits
            String alphabets = "^[A-Za-z]+$";

            Pattern PATTERN = Pattern.compile(alphaNumericREGEX);
            Pattern PATTERN1 = Pattern.compile(numericREGEX);
            Pattern PATTERN2 = Pattern.compile(alphabets);

            String response = isharesPageObjects3.SHARES_RESPONSE.getText();
            if(response.contains(SSR))
            {
                Response:
                for (int i = 2; i < response.split("\n").length; i++)
                {
                    if(response.split("\n")[i].contains(SSR))
                    {
                        String DateRange=null;
                        String flightRange=null;
                        String boardPTOffPT = null;

                        System.out.println("SSR Details : "+response.split("\n")[i]);

                        for(int j=0; j<response.split("\n")[i].split(" ").length;j++)
                        {
                            String word=response.split("\n")[i].split(" ")[j];
                            if(word.contains("-") && PATTERN2.matcher(response.split("\n")[i].split(" ")[j].replace("-","")).matches())
                            {
                                boardPTOffPT=response.split("\n")[i].split(" ")[j];
                            }
                            else if(response.split("\n")[i].split(" ")[j].contains("-") && PATTERN1.matcher(response.split("\n")[i].split(" ")[j].split("-")[0]).matches())
                            {
                                flightRange=response.split("\n")[i].split(" ")[j];
                            }
                            else if(response.split("\n")[i].split(" ")[j].contains("-") && PATTERN.matcher(response.split("\n")[i].split(" ")[j].split("-")[0]).matches())
                            {
                                DateRange=response.split("\n")[i].split(" ")[j];
                            }
                        }

                        //              	K-ED/WCHR//PTY-MEX/11JUL24-13JUL24
                        String command = (flightRange!=null)? "K-ED/" + SSR + "/" +flightRange+ "//" +DateRange: "K-ED/" + SSR + "//" +boardPTOffPT+ "/" +DateRange ;
                        gl.logCommand(logInfo, command);
                        gl.sendCmdValidateResponse(command, "ITEMS DELETED","ITEM DELETED", logInfo);
                        logInfo.pass("I delete SSR "+SSR+" from PSC Exception Table");
                    }
                }
            }
            else if(response.contains("ITEM NOT IN PSC EXC TABLE"))
                logInfo.pass(MarkupHelper.createLabel("SSR "+SSR+" not there in PSC Exception Table", ExtentColor.PURPLE));

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


