            Faker fname = new Faker(new Locale("en-US"));
            String FirstName = fname.name().firstName();
            String LastName = fname.name().lastName();
            command = "-1@" + FirstName + "/" + LastName;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "INVLD ACT/FLWG DATA NOT ENT", logInfo);

            command = "6RR";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "*", logInfo);

            command = "-1@";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "INVLD ACT/FLWG DATA NOT ENT", logInfo);

            command = "FF";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "INVALID FF/FX-DIVIDE PARTY IN PROGRESS", logInfo);

            command = "F";
            gl.logCommand(logInfo, command);
