    public void bookThePNRBetweenFirstSegmentDateAndERDate(ExtentTest logInfo) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
//                7TAW/130P/4NOV/CTO MKC
            String command = "7TAW/130P/" + gl.sharesFormatDateFromGUI(pax.getSegmentDate(0) - 2) + "/CTO MKC";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "*", logInfo);
//             -TEST/II
            command = "-" + pax.getfName() + "/" + pax.getlName();
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "*", logInfo);
//             0CM360Y15NOVPTYLAXNN1
            command = "0CM" + pax.getSegmentFlight(0) + pax.getCOS() + gl.sharesFormatDateFromGUI(pax.getSegmentDate(0) + 10) + pax.getSegmentOriginCity(0) + pax.getSegmentDestinationCity(0) + "NN1";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "ETKT ELIGIBLE", logInfo);

//             ER
            command = "ER";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "7TA DATE INVALID", logInfo);

            gl.ignoreTRNS(logInfo);

//             0CM360Y15NOVPTYLAXNN1
            command = "0CM" + pax.getSegmentFlight(0) + pax.getCOS() + gl.sharesFormatDateFromGUI(pax.getSegmentDate(0) + 10) + pax.getSegmentOriginCity(0) + pax.getSegmentDestinationCity(0) + "NN1";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "ETKT ELIGIBLE", logInfo);
//                7TAW/130P/4NOV/CTO MKC
            command = "7TAW/130P/" + gl.sharesFormatDateFromGUI(pax.getSegmentDate(0) + 2) + "/CTO MKC";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "*", logInfo);
//             -TEST/II
            command = "-" + pax.getfName() + "/" + pax.getlName();
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "*", logInfo);
//             6AA#9PTY/N123
            command = "6AA|9" + pax.getPOS() + "/N123";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "*", logInfo);
//             ER
            command = "ER";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "NO FQ EXISTS/PRICE PNR AND FILE FARE", logInfo);
//             $-$-
            command = "$-$-";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "STANDARD BAGGAGE CHARGES", logInfo);
            //             FF
            command = "FF";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "FARE QUOTE  1 FILED", logInfo);

            //             ER
            command = "ER";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "FARE QUOTE-AUTO PRICED", logInfo);

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
        }
    }

