    public void divideThePNRUsingACIEntry(ExtentTest logInfo) {
        try {

            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String newPNR = null;

//                6:XP243/10APRPTY-SAM/CARTER
//                XD
            String command = "6:XP" + pax.getSegmentFlight(0) + "/" + gl.sharesFormatDateFromGUI(pax.getSegmentDate(0)) + pax.getSegmentOriginCity(0) +
                    "-" + pax.getfName() + "/" + pax.getlName() + "\n" + "XD";
            gl.logCommand(logInfo, command);

            isharesPageObjects3.FORMSIZE_DROPDOWN.click();
            isharesPageObjects3.FORMSIZE_SELECT2.click();
            gl.copyCmdToClipboardAndPaste(command, isharesPageObjects3.FORMSIZE_SELECT2_TEXTAREA);
            isharesPageObjects3.SEND_ISHARES.click();
            gl.waitForPageReload(getDriver(), isharesPageObjects3.SHARES_RESPONSE, PAGE_LOAD_TIMEOUT);

            String response = isharesPageObjects3.SHARES_RESPONSE.getText();
            Assert.assertTrue(response.contains("PNR UPDATE PROCESSED") || response.contains("FLT NOT OPEN"));

            if (response.contains("FLT NOT OPEN")) {
                openFlight(logInfo, pax.getSegmentFlight(0), gl.sharesFormatDateFromGUI(pax.getSegmentDate(0)), pax.getSegmentOriginCity(0));

                isharesPageObjects3.FORMSIZE_DROPDOWN.click();
                isharesPageObjects3.FORMSIZE_SELECT2.click();
                gl.copyCmdToClipboardAndPaste(command, isharesPageObjects3.FORMSIZE_SELECT2_TEXTAREA);
                isharesPageObjects3.SEND_ISHARES.click();
                gl.waitForPageReload(getDriver(), isharesPageObjects3.SHARES_RESPONSE, PAGE_LOAD_TIMEOUT);

                response = isharesPageObjects3.SHARES_RESPONSE.getText();
                Assert.assertTrue(response.contains("PNR UPDATE PROCESSED"));
            }

            isharesPageObjects3.FORMSIZE_DROPDOWN.click();
            isharesPageObjects3.FORMSIZE_SELECT1.click();

            gl.logCommand(logInfo, "*" + pax.getPnr());
            gl.sendCmdValidateResponse("*" + pax.getPnr(), "DIVIDED", logInfo);

            response = isharesPageObjects3.SHARES_RESPONSE.getText();
            String[] rows = response.split("\n");

            for (int i = 0; i < rows.length; i++) {
                if (rows[i].contains("DIVIDED")) {
                    newPNR = rows[i].split("/")[1];
                }
            }
            gl.logCommand(logInfo, "*" + newPNR);
            gl.sendCmdValidateResponse("*" + newPNR, "SPLIT PARTY", logInfo);

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

