    public void FLIFOOperation(ExtentTest logInfo) {
        try {

            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String flight = pax.getSegmentFlight(0);
            String date = gl.sharesFormatDateFromGUI(0);
            String origin = pax.getSegmentOriginCity(0);
            String destination = pax.getSegmentDestinationCity(0);

            String ArrivalFlightTime = pax.getSegmentArrivalTime(0);
            String DepartFlightTime = pax.getSegmentDepartureTime(0);

            if (DepartFlightTime.length() == 4) {
                DepartFlightTime = "0" + pax.getSegmentDepartureTime(0);
            }
            if (ArrivalFlightTime.length() == 4) {
                ArrivalFlightTime = "0" + pax.getSegmentArrivalTime(0);
            }

            //2P302/09JUL OUT PTY 0700A   2P306/09JAN OUT LAX 1011A

            String command = "2P" + flight + "/" + date + " OUT " + origin + " " + DepartFlightTime;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, logInfo);

            //2P362/09JUL ON PTY 0703A

            command = "2P" + flight + "/" + date + " ON " + destination + " " + DepartFlightTime;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, logInfo);
            //2P302/09JUL OUT PTY 0700A

            command = "2P" + flight + "/" + date + " OUT " + origin + " " + DepartFlightTime;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, logInfo);

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

