    public void obtainAuxilliaryServices(ExtentTest logInfo, String AuxilliaryType) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String Date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0)-1);
            String Origin = pax.getSegmentOriginCity(0);

            String Command;

            if (AuxilliaryType.equalsIgnoreCase("TUR")) {      // 0TURCMNN1PTY28MAY-IT-FAL-2 PLUS 2
                Command = "0TURCMNN1" + Origin + Date + "-IT-FAL-2 PLUS 2";
                gl.logCommand(logInfo, Command);
                gl.sendCmdValidateResponse(Command, "TUR", logInfo);
            } else if (AuxilliaryType.equalsIgnoreCase("SUR")) {      // 0SURCMNN1PTY03MAY-TRAILWAY
                Command = "0SURCMNN1" + Origin + Date + "-TRAILWAY";
                gl.logCommand(logInfo, Command);
                gl.sendCmdValidateResponse(Command, "SUR", logInfo);
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

