                gl.logCommand(logInfo, command );
                gl.sendCmdValidateResponse(command,"INVALID","TOTAL AMOUNT EXCEEDS TICKET MAXIMUM" ,"CK FOR POSSIBLE FULL", logInfo);
                String response = isharesPageObjects3.SHARES_RESPONSE.getText();
