    public void openFlightForSeg(ExtentTest logInfo, String SegIndex) {
        try {
            int segIndex = Integer.parseInt(SegIndex);
            Passenger pax = mPassengers.get(getDriverID()).get(segIndex);
            String FlightNo = pax.getSegmentFlight(segIndex);
            String departureDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(segIndex));
            String OriginCity = pax.getSegmentOriginCity(segIndex);

            isharesPageObjects3.FORMSIZE_DROPDOWN.click();
            isharesPageObjects3.FORMSIZE_SELECT2.click();
            gl.waitForProfileLoad();
            String command = "6:*A" + FlightNo + "/" + departureDate + OriginCity;
            gl.logCommand(logInfo, command);
            gl.sendCmdForForm2ValidateResponse(command, logInfo);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            if (!isharesPageObjects3.SHARES_RESPONSE.getText().contains("SHIP ASSIGNED")) {
                String EqpNumber = "";
                if (globalConstants.testEnv.equalsIgnoreCase("sharesCURL")) {
                    EqpNumber = isharesPageObjects3.SHARES_RESPONSE.getText().substring(149, 152);
                } else {
//                    EqpNumber = isharesPageObjects1.SHARES_RESPONSE.getText().substring(157, 161);
                    EqpNumber = isharesPageObjects3.SHARES_RESPONSE.getText().substring(153, 156);
                }

                String command2 = "6:I*F" + EqpNumber;
                gl.logCommand(logInfo, command2);
                gl.sendCmdForForm2ValidateResponse(command2, logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                String FleetNumber = "";

                if (globalConstants.testEnv.equalsIgnoreCase("sharesCURL")) {
                    FleetNumber = isharesPageObjects3.SHARES_RESPONSE.getText().substring(128, 132);
                } else {
                    FleetNumber = isharesPageObjects3.SHARES_RESPONSE.getText().substring(130, 134);
                }

                System.out.println("Flight ship index " + FleetNumber);
                String command3 = "6:CA" + departureDate + "\n" + FlightNo + OriginCity + FleetNumber;
                gl.logCommand(logInfo, command3);
                isharesPageObjects3.FORMSIZE_SELECT2_TEXTAREA.click();
                gl.copyCmdToClipboardAndPaste(command3, isharesPageObjects3.FORMSIZE_SELECT2_TEXTAREA);
                isharesPageObjects3.SEND_ISHARES.click();
                gl.waitForProfileLoad();
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                String response = isharesPageObjects3.SHARES_RESPONSE.getText();
                gl.logResponse(logInfo, response);
                Assert.assertTrue(response.contains("SHIP ASSIGNED"));
            }

            if (isharesPageObjects3.SHARES_RESPONSE.getText().contains("SHIP ASSIGNED")) {
                System.out.println("SHIP ASSIGNED SUCCESSFULLY: " + FlightNo);
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");

        }

    }

