    public void downgrade_lower_cabin_6GI_multiple_surname_withList(ExtentTest logInfo, String SegIndex, String ListType)
    {
        try {

            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String origin = pax.getSegmentOriginCity(0);
            boolean repeatTrns;
            int[] paxIDs = new int[2];
            String response;

            gl.ignoreTRNS(logInfo);

            for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++)
            {

                for (int a = 0; a < 2; a++)
                {
                    repeatTrns = true;
                    //                ***** Entering Base command *****

                    while (repeatTrns )
                    {

                        String Cmd =isharesPage2.addGICmd(origin, i);
                        gl.logCommand(logInfo, Cmd);
                        gl.copyCmdToClipboardAndPaste(Cmd, isharesPageObjects3.FORMSIZE_SELECT2_TEXTAREA);

                        gl.waitForProfileLoad();

                        isharesPageObjects3.SEND_ISHARES.click();
                        gl.waitForProfileLoad();
                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                        response = isharesPageObjects3.SHARES_RESPONSE.getText();
                        gl.logResponse(logInfo,response);

                        if (response.contains("NOT OPEN"))
                        {
                            isharesPage2.openFlight(logInfo, mPassengers.get(getDriverID()).get(0).getSegmentFlight(0), gl.sharesFormatDateFromGUI(mPassengers.get(getDriverID()).get(0).getSegmentDate(0)), origin);
                            gl.ignoreTRNS(logInfo);
                        } else if (response.contains("MULTIPLE ITEMS")) {
                            paxIDs = getPaxIDs(response, i);
                            repeatTrns = false;
                        } else {
                            repeatTrns = false;
                        }

                    }

                    //6:LGI-203.Y
                    String MultiListCmd = "6:LGI-" + paxIDs[a] + "." + pax.getCOS() + "|NS" + "\n" + "B0";
                    gl.logCommand(logInfo, MultiListCmd);
                    gl.copyCmdToClipboardAndPaste(MultiListCmd, isharesPageObjects3.FORMSIZE_SELECT2_TEXTAREA);
                    isharesPageObjects3.SEND_ISHARES.click();

                    gl.waitForProfileLoad();
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    gl.logResponse(logInfo,isharesPageObjects3.SHARES_RESPONSE.getText());


                    if(isharesPageObjects3.SHARES_RESPONSE.getText().contains("GENERAL  INFORMATION"))
                    {
                        //**** PRIMARY DOCUMENT DETAILS*****
                        String IncompleteADCInfo;
                        if (globalConstants.testEnv.equalsIgnoreCase("sharesCURL") || globalConstants.testEnv.equalsIgnoreCase("sharesD3URL")) {
                            IncompleteADCInfo = isharesPageObjects3.SHARES_RESPONSE.getText();
                        } else {
                            IncompleteADCInfo = isharesPageObjects3.INPUT_TEXT_AREA_ROWS24.getText();
                        }

                        System.out.println(IncompleteADCInfo);

                        String CompleteADCInfo = isharesPage2.add_PrimaryADC(IncompleteADCInfo, i);
                        System.out.println(CompleteADCInfo);
                        gl.logCommand(logInfo,CompleteADCInfo);

                        while (!isharesPage2.validatePrimaryADCMultiInitial(CompleteADCInfo, logInfo, i))  //to check Primary details are entered properly or not
                        {
                            CompleteADCInfo = isharesPage2.reformPrimaryADC(i);

                        }

                        gl.waitForProfileLoad();
                        gl.logResponse(logInfo,isharesPageObjects3.SHARES_RESPONSE.getText());
                        logInfo.pass("Primary Document Details entered for " + mPassengers.get(getDriverID()).get(i).getFullName());

//                   **** SECONDARY DOCUMENT DETAILS  ****

                        if (isharesPageObjects3.SHARES_RESPONSE.getText().contains("DOCTYPE: P-PASSPORT") || isharesPageObjects3.SHARES_RESPONSE.getText().contains("DOCUMENT INFORMATION"))
                        {
                            if (globalConstants.testEnv.equalsIgnoreCase("sharesCURL") || globalConstants.testEnv.equalsIgnoreCase("sharesD3URL")) {

                                String IncompleteDoctypeInfo_Adult = isharesPageObjects3.SHARES_RESPONSE.getText();
                                System.out.println("IncompleteDoctypeInfo_Adult : \n" + IncompleteDoctypeInfo_Adult + "\n");
                                String CompleteDoctypeInfo_Adult = isharesPage2.add_SecondaryADC(IncompleteDoctypeInfo_Adult);
                                System.out.println("CompleteDoctypeInfo_Adult : \n" + CompleteDoctypeInfo_Adult + "\n");

                                while (!isharesPage2.validateSecondaryADCMultiInitial(CompleteDoctypeInfo_Adult, logInfo, i)) {
                                    CompleteDoctypeInfo_Adult = isharesPage2.reformSecondaryADC();
                                }

                            } else {
                                String IncompleteDoctypeInfo_Adult = isharesPageObjects3.INPUT_TEXT_AREA_ROWS24.getText();
                                System.out.println("IncompleteDoctypeInfo_Adult : \n" + IncompleteDoctypeInfo_Adult + "\n");
                                String CompleteDoctypeInfo_Adult = isharesPage2.add_SecondaryADC(IncompleteDoctypeInfo_Adult);
                                System.out.println("CompleteDoctypeInfo_Adult : \n" + CompleteDoctypeInfo_Adult + "\n");

                                while (!isharesPage2.validateSecondaryADCMultiInitial(CompleteDoctypeInfo_Adult, logInfo, i)) {
                                    CompleteDoctypeInfo_Adult = isharesPage2.reformSecondaryADC();
                                }
                            }

                            logInfo.pass("Secondary Document Details entered for :" + mPassengers.get(getDriverID()).get(i).getFullName());
                        }

                        Assert.assertTrue(isharesPageObjects3.SHARES_RESPONSE.getText().contains("SEATS ASSIGNED"), "Checkin Unsuccessful");
                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    }//end of if
                    else if(isharesPageObjects3.SHARES_RESPONSE.getText().contains("PAX ALREADY CHECKED IN"))
                        logInfo.info(MarkupHelper.createLabel("PAX ALREADY CHECKED IN", ExtentColor.PURPLE));

                }//end of index for loop

            }// end of pax for loop

            mText.put(getDriverID(), isharesPageObjects3.SHARES_RESPONSE.getText());
            isharesPageObjects3.FORMSIZE_DROPDOWN.click();
            isharesPageObjects3.FORMSIZE_SELECT1.click();

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public int[] getPaxIDs(String response, int paxIndex) {
        int x = 0;
        int[] paxIDs = new int[2];

        for (int i = 0; i < response.split("\n").length; i++) {
            if (response.split("\n")[i].contains(mPassengers.get(getDriverID()).get(paxIndex).getPnr2()) || response.split("\n")[i].contains(mPassengers.get(getDriverID()).get(paxIndex).getPnr())) {
                paxIDs[x++] = Integer.parseInt(response.split("\n")[i].substring(0, 4).trim());
            }
        }
        return paxIDs;
    }

