    public void enterXP_XSCommandToAddOSIRemarks(ExtentTest logInfo, String RemarkType) {
        try {
            gl.ignoreTRNS(logInfo);
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String Origin = pax.getSegmentOriginCity(0);
            String flight = pax.getSegmentFlight(0);
            String Date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));

            int i =0;
            for (Passenger pax1 : mPassengers.get(getDriverID()))
            {
                //   6-XP837/6MARBOG-HIMA/ONE
                //   XSAMEDATMNN

//                XSA--> Constant for addition
//                TM/CM---> Carrier Code
//                NN1--> No of Passenger
                String RemarkLine2 = "";

                if (RemarkType.equalsIgnoreCase("MEDA"))
                {
                    RemarkLine2 = "XSAMEDATMNN";
                }
                else if (RemarkType.equalsIgnoreCase("BLND"))
                {
                    RemarkLine2 = "XSABLNDCMNN";
                }
                else if (RemarkType.equalsIgnoreCase("VGML"))
                {
                    RemarkLine2 = "XSAVGMLTMNN";
                }
                else if (RemarkType.equalsIgnoreCase("AISLE"))
                {
                    RemarkLine2 = "XSANSSTCM.NN1-" + pax1.getlName() + "*ND NON-SMKG AISLE SEAT";
                }
                else if (RemarkType.equalsIgnoreCase("UA"))
                {
                    if(i==1){
                        break;
                    }
                    //  XIAUA1031C06MARPTYIAH
                    RemarkLine2 = "XIA" + "UA" + pax1.getSegmentFlight(1) + pax1.getCOS() +
                            gl.sharesFormatDateFromGUI(pax.getSegmentDate(1)) + pax1.getSegmentOriginCity(1)
                            + pax1.getSegmentDestinationCity(1);
                }
                else if (RemarkType.equalsIgnoreCase("XD"))
                {
                    //  XD
                    RemarkLine2 = "XD";
                    if(i==2){
                        break;
                    }
                }
                else if (RemarkType.equalsIgnoreCase("XS"))
                {
                    //  XS
                    RemarkLine2 = "XS*";
                }else if (RemarkType.equalsIgnoreCase("XIX")) {
                    if(i==1){
                        break;
                    }
                    //  XIX
                    RemarkLine2 = "XIX";
                }
                else if (RemarkType.equalsIgnoreCase("XS_OSI"))
                {
                    //  XS@1OSI/YY3OSI CM PAX VIP
                    RemarkLine2 = "XS@1OSI/YY3OSI CM PAX VIP";
                }
                else if (RemarkType.equalsIgnoreCase("XS_ESAN_SSR"))
                {
                    //  XS@SS56646CMNN1UIOPTY0153Y06MAR-1HIMARI/TWO.DOG
                    flight = pax.getSegmentFlight(0);
                    int Size = mPassengers.get(getDriverID()).size();
                    String destinationCity = pax.getSegmentDestinationCity(0);
                    String COS = pax.getCOS();
                    String Airline = pax.getAirline(0);
                    RemarkLine2 = "XS@SS56646CMNN" + Size + Origin + destinationCity + flight + COS + Date + "-1" + pax1.getfName() + "/" + pax1.getlName() + ".DOG";
                }
                else if(RemarkType.equalsIgnoreCase("XS_InvalidSeg"))
                {
                    //  XS@8
                    RemarkLine2 = "XS@8";
                }
                else if (RemarkType.equalsIgnoreCase("XSA_OSI"))
                {
                    //  XSAOSI/YY3OSI CM PAX VIP
                    RemarkLine2 = "XSAOSI/YY3OSI CM PAX VIP";
                }

                String command = "6:XP" + flight + "/" + Date + Origin + "-" + pax1.getfName() + "/" + pax1.getlName() + "\n" + RemarkLine2;

                if (RemarkType.equalsIgnoreCase("XS_ESAN_SSR") || RemarkType.equalsIgnoreCase("XS_InvalidSeg") || RemarkType.equalsIgnoreCase("XS_OSI")) {
                    gl.logCommand(logInfo,command);
                    gl.sendCopiedCmdValidateResponse2(logInfo, command, "UPDATE NOT PROCESSED","MULTIPLE ITEMS","PNR UPDATE PROCESSED");

                } else if (RemarkType.equalsIgnoreCase("XS")) {
                    gl.logCommand(logInfo,command);
                    gl.sendCopiedCmdValidateResponse2(logInfo, command, "API COMPLETED", "MULTIPLE ITEMS","XS@");
                }  else if (RemarkType.equalsIgnoreCase("XIX")) {
                    gl.logCommand(logInfo, command);
                    gl.sendCopiedCmdValidateResponse2(logInfo, command, "LAST ITIN CHANGE UNDONE","MULTIPLE ITEMS");
                }
                else {
                    gl.logCommand(logInfo,command);
                    gl.sendCopiedCmdValidateResponse2(logInfo, command, "PNR UPDATE PROCESSED", "MULTIPLE ITEMS", "NOT OPEN");
                }


                String response= isharesPageObjects3.SHARES_RESPONSE.getText();

                if (response.contains("NOT OPEN")) {
                    openFlight(logInfo, mPassengers.get(getDriverID()).get(0).getSegmentFlight(0), gl.sharesFormatDateFromGUI(mPassengers.get(getDriverID()).get(0).getSegmentDate(0)), Origin);
                    gl.ignoreTRNS(logInfo);
                    gl.logCommand(logInfo, command);
                    gl.sendCopiedCmdValidateResponse2(logInfo, command, "PNR UPDATE PROCESSED", "MULTIPLE ITEMS");
                }


                    if (isharesPageObjects3.SHARES_RESPONSE.getText().contains("MULTIPLE ITEMS"))
                    {
                    response = isharesPageObjects3.SHARES_RESPONSE.getText();

                    //Capturing ID for the PNR
                    int index = response.indexOf(pax.getPnr());
                    String indexVal = response.substring((index - 27), (index - 24)).trim();

                    //       6:CQA/C-***
                    String cmd = "6:CQA/C-***";

                    gl.logCommand(logInfo,cmd);
                    gl.sendCmdValidateResponse(cmd,"ACI AAA PROFILE INFORMATION",logInfo);
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                    //  6:LXP-125
                     String MultiListCmd = "6:LXP-" + indexVal; // Selected pax with ID
                     gl.logCommand(logInfo, MultiListCmd);
                     gl.sendCopiedCmdValidateResponse2(logInfo, MultiListCmd, "LAST ITIN CHANGE UNDONE", "PNR UPDATE PROCESSED","XS@");

                    }

                i++;
            }
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


