    public void downgrade_lower_cabin_6GI_multiple_surname_withListWithNA(ExtentTest logInfo, String SegIndex, String ListType) {
        try {
            gl.ignoreTRNS(logInfo);

            int segIndex = Integer.parseInt(SegIndex);
            Passenger pax = mPassengers.get(getDriverID()).get(segIndex);
            String Origin = pax.getSegmentOriginCity(segIndex);

            String flight = pax.getSegmentFlight(segIndex);
            String Date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(segIndex));


            for (Passenger passenger : mPassengers.get(getDriverID())) {
                //6:GI391/12JUNPTY-TEST/FON.K|NA

                String command = "6:GI" + flight + "/" + Date + Origin + "-" + passenger.getfName() + "/" + passenger.getlName() + "." + pax.getCOS() + "|NA";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "SEATS ASSIGNED", "MULTIPLE ITEMS", logInfo);

                if (isharesPageObjects3.SHARES_RESPONSE.getText().contains("MULTIPLE ITEMS")) {

                    String response = isharesPageObjects3.SHARES_RESPONSE.getText();

                    //Capturing ID for the PNR
                    if(pax.getPnr()!=null)
                    {
                        //Capturing ID for the PNR
                        int index = response.indexOf(pax.getPnr());
                        String indexVal = response.substring((index - 27), (index - 24)).trim();

                        String MultiListCmd = "6:LGI-" + indexVal + "." + pax.getCOS() + "|"+ListType;
                        gl.logCommand(logInfo, MultiListCmd);
                        gl.sendCmdValidateResponse(MultiListCmd, logInfo);
                    }

                    if(pax.getPnr2()!=null)
                    {
                        //Capturing ID for the PNR
                        int index = response.indexOf(pax.getPnr2());
                        String indexVal = response.substring((index - 27), (index - 24)).trim();

                        String MultiListCmd = "6:LGI-" + indexVal + "." + pax.getCOS() + "|"+ListType;
                        gl.logCommand(logInfo, MultiListCmd);
                        gl.sendCmdValidateResponse(MultiListCmd, logInfo);
                    }

                }
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


