    public void rebookTheSegmentWithTheNewClassOfServiceAndDate(ExtentTest logInfo, String TotalSegments) {
        try {

            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String COS = pax.getCOS();
            String Date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(1));

            //.1@A@30SEP
            String MultiListCmd = "." + TotalSegments + "@" + COS + "@" + Date;
            gl.logCommand(logInfo, MultiListCmd);
            gl.sendCmdValidateResponse(MultiListCmd, "002-OK-", logInfo);


        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

