    public void enterOCMAUTHCommand(ExtentTest logInfo, String Entry) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);

            if (Entry.equalsIgnoreCase("OCMAUTH")) {
                //OCMAUTH*
                String command = "OCMAUTH*";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "VET TAPE PROCESSING STATUS", logInfo);
            } else if (Entry.equalsIgnoreCase("OCMAUTH_START")) {
                //OCMAUTH/START1
                String command = "OCMAUTH/START1";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "VET TAPE PROCESSING NOT A DETAIL FLT USER", logInfo);
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

