    public void enterRG_CommandToValidateErrorResponse(ExtentTest logInfo, String Entry) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);

            String command = "6:RG." + Entry;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "ONLY VALID WITH MM STATUS / SPACE AVAIL PAX", "FLT NOT OPEN", logInfo);

            if(isharesPageObjects3.SHARES_RESPONSE.getText().contains("FLT NOT OPEN")){
                isharesPage2.openFlight(logInfo, pax.getSegmentFlight(0), gl.sharesFormatDateFromGUI(pax.getSegmentDate(0)), pax.getSegmentOriginCity(0));
                isharesPageObjects3.FORMSIZE_DROPDOWN.click();
                isharesPageObjects3.FORMSIZE_SELECT1.click();

                command = "6:RG." + Entry;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "ONLY VALID WITH MM STATUS / SPACE AVAIL PAX", logInfo);

            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }



