    public void verifyCarrierSchedule(ExtentTest logInfo, String carrier1, String carrier2, String origin, String destination)
    {
        try {
            String startDate = gl.sharesFormatDateFromGUI(Integer.parseInt("02"));
            String command = "";
            if (carrier2.contains("DL"))
            {
                //  S HNLLAX-UA/AA
                command = "S "+origin+destination+"-"+carrier1+"/"+carrier2;
                gl.logCommand(logInfo,command);
                gl.sendCmdValidateResponse(command,"ALTERNATE SERVICE", carrier1, carrier2, logInfo);
            }
            else if(carrier1.contains("CM"))
            {
                //  S LAXPTY /1PTY/1LAX/1-CM
                command = "S "+origin+destination+" /1"+destination+"/1"+origin+"/1-"+carrier1;
                gl.logCommand(logInfo,command);
                gl.sendCmdValidateResponse(command,"ALTERNATE SERVICE", carrier1, logInfo);
            }
            else if(carrier1.equals("AA") && carrier2.isEmpty())
            {
                //  S LAXSEA -2-AA
                command = "S "+origin+destination+" -2-"+carrier1;
                gl.logCommand(logInfo,command);
                gl.sendCmdValidateResponse(command,"ALTERNATE SERVICE", carrier1, logInfo);
            }
            else
            {
                //  S HNLLAX-UA/AA
                command = "S "+origin+destination+"-"+carrier1+"/"+carrier2;
                gl.logCommand(logInfo,command);
                gl.sendCmdValidateResponse(command,"ALTERNATE SERVICE", carrier1, carrier2, logInfo);
                //  AC HNL
                command = "AC "+origin;
                gl.logCommand(logInfo,command);
                gl.sendCmdValidateResponse(command,"ALTERNATE SERVICE", carrier1, carrier2, logInfo);
                //  S HNLLAX-UA/AA
                command = "S "+origin+destination+"-"+carrier1+"/"+carrier2;
                gl.logCommand(logInfo,command);
                gl.sendCmdValidateResponse(command,"ALTERNATE SERVICE", carrier1, carrier2, logInfo);
                //  AC LAX
                command = "AC /"+destination;
                gl.logCommand(logInfo,command);
                gl.sendCmdValidateResponse(command,"ALTERNATE SERVICE", carrier1, carrier2, logInfo);
                //  S17JUNLAXNYC800P-AA/UA
                command = "S"+startDate+destination+"NYC800P-"+carrier2+"/"+carrier1;
                gl.logCommand(logInfo,command);
                gl.sendCmdValidateResponse(command,"ALTERNATE SERVICE", carrier1, carrier2, logInfo);
            }
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
        }
    }

