            command = "PAE";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "INVALID DELIMITER", logInfo);

//          PAAA

            command = "PAAA";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "INVLD FORMAT", logInfo);

//           PAYA/CCC/DD

            command = "PAYA/CCC/DD";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "NOT AUTHORIZED USER", logInfo);


//          PAYA/LAX/45
            command = "PAYA/LAX/45";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "NOT AUTHORIZED USER", logInfo);

//          PAAA/LAX

            command = "PAAA/LAX";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "INVLD FORMAT", logInfo);

//           PABB/LAX
            command = "PABB/LAX";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "INVLD FORMAT", logInfo);


//            PAYY*
            command = "PAYY*";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "INVLD FORMAT", logInfo);

//          PAYAA/LAX/27JAN

            command = "PAYAA/LAX/27JAN";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "NOT AUTHORIZED USER", logInfo);

//           PAYAA/LAX#27JAN

