    public void tTYMessageForWHCRSSR(ExtentTest logInfo,String totalSegments) {
        try {

            Passenger pax = mPassengers.get(getDriverID()).get(0);

            String Line2;   //PTYRMCM
            if (globalConstants.testEnv.equalsIgnoreCase("sharesURL")) {
                Line2 = "PTYRMCM";
            } else {
                Line2 = "CLTYSCM";
            }

            String UniquePnr = isharesPage2.GenerateUniquePnr(logInfo);
            pax.setUniqueTTYPnr(UniquePnr);
            String addSSrToTTY="";
            String ssrCommand="";
            String flightNum=null;
            String BasicAirlinePnr;


            for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {

                pax = mPassengers.get(getDriverID()).get(i);


                if (pax.getPaxType().equalsIgnoreCase("CHD")) {

                    addSSrToTTY = addSSrToTTY+"\n";

                } else {
                    for (int j = 0; j < pax.getTotalSegments(); j++) {
                        if (pax.getSegmentFlight(j).length() == 3) {
                            flightNum = "0" + pax.getSegmentFlight(j);

                        } else {
                            flightNum = pax.getSegmentFlight(j);
                        }

                        ssrCommand = "SSRWCHRNN1" + pax.getAirline(j) + flightNum + pax.getCOS() + pax.getSegmentOriginCity(j) + pax.getSegmentDestinationCity(j)
                                + gl.sharesFormatDateFromGUI(pax.getSegmentDate(j))
                                + "-1" + pax.getfName() + "/" + pax.getlName();

                        addSSrToTTY = addSSrToTTY + ssrCommand + "\n";

                    }
                }
            }


            BasicAirlinePnr = "Y" + "\n" +
                    Line2 + "\n" +
                    ".MUCRM1A" + " 251335" + "\n" +
                    "MUC1A" + " " + UniquePnr + "\n" +
                    isharesPage2.GDSPnrTotalPax() + isharesPage2.GDSPnrTotalSegments(totalSegments)
                    + "\n" + addSSrToTTY;

            isharesPageObjects3.FORMSIZE_DROPDOWN.click();
            isharesPageObjects3.FORMSIZE_SELECT24.click();

            gl.logCommand(logInfo, BasicAirlinePnr);
            System.out.println("BaseCommand " + BasicAirlinePnr);
            gl.copyCmdToClipboardAndPaste(BasicAirlinePnr, isharesPageObjects3.FORMSIZE_SELECT2_TEXTAREA);

            isharesPageObjects3.SEND_ISHARES.click();
            logInfo.pass("I passed TTY message");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            gl.waitForProfileLoad();
            String response = isharesPageObjects3.SHARES_RESPONSE.getText();
            gl.logResponse(logInfo, response);
            Assert.assertTrue(response.contains("MESSAGE ACCEPTED"));

            retrieveIttyMessage(logInfo,UniquePnr);

            totalSegments="XX";
            BasicAirlinePnr = "Y" + "\n" +
                    Line2 + "\n" +
                    ".MUCRM1A" + " 251335" + "\n" +
                    "MUC1A" + " " + UniquePnr + "\n" +
                    isharesPage2.GDSPnrTotalPax() + isharesPage2.GDSPnrTotalSegments(totalSegments)
                    + "\n" + addSSrToTTY;

            isharesPageObjects3.FORMSIZE_DROPDOWN.click();
            isharesPageObjects3.FORMSIZE_SELECT24.click();

            gl.logCommand(logInfo, BasicAirlinePnr);
            System.out.println("BaseCommand " + BasicAirlinePnr);
            gl.copyCmdToClipboardAndPaste(BasicAirlinePnr, isharesPageObjects3.FORMSIZE_SELECT2_TEXTAREA);

            isharesPageObjects3.SEND_ISHARES.click();
            logInfo.pass("I passed TTY message");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            gl.waitForProfileLoad();
            String response1 = isharesPageObjects3.SHARES_RESPONSE.getText();
            gl.logResponse(logInfo, response1);
            Assert.assertTrue(response1.contains("MESSAGE ACCEPTED"));

            retrieveIttyMessage(logInfo,UniquePnr);

            logInfo.pass("I enter TTY message to generate PNR");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }


    }

    public void updateTheInTime(ExtentTest logInfo) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String flightNo = pax.getSegmentFlight(0);
            String startDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String destCity = pax.getSegmentDestinationCity(0);
            int time=0;

            String checkQueueList = "2" + pax.getSegmentFlight(0) + "/" + startDate;
            gl.logCommand(logInfo, checkQueueList);
            gl.sendCmdValidateResponse(checkQueueList, pax.getSegmentFlight(0), "SKED", logInfo);
            String response=isharesPageObjects3.SHARES_RESPONSE.getText();
            String[] res=response.split("\n");
            String res1 = res[4];
            String[] var=res1.split(" ");
            for(int i=0;i<var.length;i++){
                if(!var[i].isEmpty()){
                    if(!var[i].equals(destCity)){

                        String segment=var[i].trim();
                        String value=segment.substring(0,segment.length()-1);
                        time=Integer.parseInt(value)+10;
                        String str= String.valueOf(time);
                        String x=str.substring(str.length()-2);
                        int z=Integer.parseInt(x);
                        int y=58;
                        if(z>y){
                            time=time-42;
                        }

                        break;
                    }
                }

            }


            //\par I\tab Y
            //\par M\tab CLTYSCM
            //\par M\tab .MUCRM1A 251335
            //\par M\tab FAM
            //\par M\tab 2P761/09JUL IN LIM 350P

            checkQueueList = "Y" + "\n" + "CLTYSCM" + "\n" + ".MUCRM1A 251335" + "\n" + "FAM" + "\n" +
                    "2P" + flightNo + "/" + startDate + " IN " + destCity +" " +time + "P";
            gl.logCommand(logInfo, checkQueueList);
            gl.sendCopiedCmdValidateResponse2(logInfo, checkQueueList, "MESSAGE ACCEPTED");

            Thread.sleep(5000);
            checkQueueList = "2" + pax.getSegmentFlight(0) + "/" + startDate;
            gl.logCommand(logInfo, checkQueueList);
            gl.sendCmdValidateResponse(checkQueueList, destCity + "/IN","SKED", logInfo);

            String response1 = isharesPageObjects3.SHARES_RESPONSE.getText();
            if (!response1.contains(destCity + "/IN")) {
                gl.waitProgress();
                checkQueueList = "2" + pax.getSegmentFlight(0) + "/" + startDate;
                gl.logCommand(logInfo, checkQueueList);
                gl.sendCmdValidateResponse(checkQueueList, destCity + "/IN", logInfo);
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

    }

    public void updateThePRETime(ExtentTest logInfo) {

        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String flightNo = pax.getSegmentFlight(0);
            String startDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String destCity = pax.getSegmentDestinationCity(0);
            int time=0;
            String checkQueueList = "2" + pax.getSegmentFlight(0) + "/" + startDate;
            gl.logCommand(logInfo, checkQueueList);
            gl.sendCmdValidateResponse(checkQueueList, pax.getSegmentFlight(0), "SKED", logInfo);
            String response=isharesPageObjects3.SHARES_RESPONSE.getText();
            String[] res=response.split("\n");
            String res1 = res[4];
            String[] var=res1.split(" ");

            for(int i=0;i<var.length;i++){
                if(!var[i].isEmpty()){
                    if(!var[i].equals(destCity)){

                        String segment=var[i].trim();
                        String value=segment.substring(0,segment.length()-1);
                        time=Integer.parseInt(value)-10; //subtracting the destination location time by 10
                        String str= String.valueOf(time);
                        String x=str.substring(str.length()-2);
                        int z=Integer.parseInt(x);
                        int y=58; //minute value will be between 01 to 59 . considering 58 has the fixed value
                        if(z>y){
                            time=time-42; //subtracting the time with 42 some constant value so that it wont end with value 59 or more
                        }

                        break;
                    }
                }

            }

            gl.ignoreTRNS(logInfo);

            //\par I\tab Y
            //\par M\tab PTYRMCM
            //\par M\tab .MUCRM1A 251335
            //\par M\tab FAM
            //\par M\tab 2P360/09AUG PRE LAX 0758A
            checkQueueList = "Y" + "\n" + "CLTYSCM" + "\n" + ".MUCRM1A 251335" + "\n" + "FAM" + "\n" +
                    "2P" + flightNo + "/" + startDate + " PRE " + destCity + " " + time + "A";
            gl.logCommand(logInfo, checkQueueList);
            gl.sendCopiedCmdValidateResponse2(logInfo, checkQueueList, "MESSAGE ACCEPTED");

            Thread.sleep(5000);
            checkQueueList = "2" + pax.getSegmentFlight(0) + "/" + startDate;
            gl.logCommand(logInfo, checkQueueList);
            gl.sendCmdValidateResponse(checkQueueList, destCity + "/PRE", "SKED", logInfo);

            String response1 = isharesPageObjects3.SHARES_RESPONSE.getText();

            if (!response1.contains(destCity + "/PRE")) {
                gl.waitProgress();
                checkQueueList = "2" + pax.getSegmentFlight(0) + "/" + startDate;
                gl.logCommand(logInfo, checkQueueList);
                gl.sendCmdValidateResponse(checkQueueList, destCity + "/PRE", logInfo);
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

