    public void toReinstateMisconnectPassengers(ExtentTest logInfo) {

        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String ConnectingFlight = pax.getSegmentFlight(0);
            String Flight = pax.getSegmentFlight(1);
            String ConnectingOrigin = pax.getSegmentOriginCity(1);
            String Date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));

            String cancelMisconnectCmd = "6:CX" + Flight + "/" + Date + ConnectingOrigin + "." + ConnectingFlight;
            gl.logCommand(logInfo, cancelMisconnectCmd);
            gl.sendCmdValidateResponse(cancelMisconnectCmd, "PAX CONNECTING FROM FLT", "SHIP NOT ASSIGNED", "ENTER FROM CONTROLLING CRT","NO PAX TO CANCEL/REINSTATE", logInfo);
            System.out.println("cmd : " + cancelMisconnectCmd);

            if (isharesPageObjects3.SHARES_RESPONSE.getText().contains("SHIP NOT ASSIGNED")) {
                isharesPage2.openFlight(logInfo, ConnectingFlight, Date, ConnectingOrigin);
                isharesPageObjects3.FORMSIZE_DROPDOWN.click();
                isharesPageObjects3.FORMSIZE_SELECT1.click();
                gl.waitForProfileLoad();
                gl.sendCmdValidateResponse(cancelMisconnectCmd, "PAX CONNECTING FROM FLT", "ENTER FROM CONTROLLING CRT", logInfo);
            }

            if (isharesPageObjects3.SHARES_RESPONSE.getText().contains("ENTER FROM CONTROLLING CRT")) {
                String command = "6-CQA" + "/" + "C***";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "ASSIGNED CONTROLLING SET FOR", "CONTROLLING SET CHANGED TO", logInfo);
                gl.sendCmdValidateResponse(cancelMisconnectCmd, "PAX CONNECTING FROM FLT", "CANCELLED","NO PAX TO CANCEL/REINSTATE", logInfo);
            }

            //            6:CX138/11OCTPTY.247|@

            String reinstateMisconnectCmd = "6:CX" + Flight + "/" + Date + ConnectingOrigin + "." + ConnectingFlight + "|@";
            gl.logCommand(logInfo, reinstateMisconnectCmd);
            gl.sendCmdValidateResponse(reinstateMisconnectCmd, "PAX CONNECTING FROM FLT", "REINSTATED", logInfo);

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

